INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(721889, 76670, 18655, '<td valign="top">Niiice! Love the colors!</td>', 'Niiice! Love the colors!', '2004-05-17 01:02:14.000000', NULL, 1),
(721891, 77014, 18655, '<td valign="top">Great idea - and nicely done!</td>', 'Great idea - and nicely done!', '2004-05-17 01:02:51.000000', NULL, 1),
(721893, 76347, 18098, '<td valign="top">I luv the colors and that cute little pink tongue!  What a great pic!</td>', 'I luv the colors and that cute little pink tongue!  What a great pic!', '2004-05-17 01:02:58.000000', NULL, 1),
(721896, 77039, 18655, '<td valign="top">Beautiful! - B&amp;W was definitely a great choice here!</td>', 'Beautiful! - B&W was definitely a great choice here!', '2004-05-17 01:04:08.000000', NULL, 1),
(721897, 76694, 18655, '<td valign="top">Pshyco cat!</td>', 'Pshyco cat!', '2004-05-17 01:04:34.000000', NULL, 1),
(721898, 76938, 16301, '<td valign="top">I love reflections, this is just perfect. Very symmetrical.<br/> <br/>Good luck...</td>', 'I love reflections, this is just perfect. Very symmetrical. Good luck...', '2004-05-17 01:04:43.000000', NULL, 1),
(721910, 76775, 21367, '<td valign="top">Great DOF, I find those little whatever they are above and to the left of the tulip distracting.  Looks like blending tool, I might have used the cloning tool to remove whatever was there.</td>', 'Great DOF, I find those little whatever they are above and to the left of the tulip distracting.  Looks like blending tool, I might have used the cloning tool to remove whatever was there.', '2004-05-17 01:12:19.000000', NULL, 1),
(721913, 76697, 21367, '<td valign="top">Very nice, I think the light could have been just a tad better so that we could get more detail of the bee.</td>', 'Very nice, I think the light could have been just a tad better so that we could get more detail of the bee.', '2004-05-17 01:14:15.000000', NULL, 1),
(721914, 76495, 21367, '<td valign="top">I like this one, the crop might be a little tight on the side for me but still a very good shot.</td>', 'I like this one, the crop might be a little tight on the side for me but still a very good shot.', '2004-05-17 01:15:28.000000', NULL, 1),
(721916, 77055, 21367, '<td valign="top">Kind of cool, If we could see more color of your eyes would make this a better shot for me.  Creative.</td>', 'Kind of cool, If we could see more color of your eyes would make this a better shot for me.  Creative.', '2004-05-17 01:17:06.000000', NULL, 1),
(721919, 76006, 17166, '<td valign="top">The highlights in the veil are a bit strong, taking attention away from her face, otherwise very nice pose, expression, and lighting.</td>', 'The highlights in the veil are a bit strong, taking attention away from her face, otherwise very nice pose, expression, and lighting.', '2004-05-17 01:17:41.000000', NULL, 1),
(721920, 75891, 18098, '<td valign="top">Excellent picture.</td>', 'Excellent picture.', '2004-05-17 01:17:43.000000', NULL, 1),
(721921, 77182, 21367, '<td valign="top">Whoa...This one scared me when it popped up, but I like it very much.  Crystal clear and fisheye add tremendously.  Great job.</td>', 'Whoa...This one scared me when it popped up, but I like it very much.  Crystal clear and fisheye add tremendously.  Great job.', '2004-05-17 01:18:24.000000', NULL, 1),
(721922, 76960, 18098, '<td valign="top">Nice colors.  A fun picture.</td>', 'Nice colors.  A fun picture.', '2004-05-17 01:18:38.000000', NULL, 1),
(721924, 77168, 7291, '<td valign="top">Wow!  What a great picture.  The vigneting and grain are perfect touches.</td>', 'Wow!  What a great picture.  The vigneting and grain are perfect touches.', '2004-05-17 01:19:00.000000', NULL, 1),
(721926, 77137, 21367, '<td valign="top">Awesome...Excellent shot.  Great Detail and DOF</td>', 'Awesome...Excellent shot.  Great Detail and DOF', '2004-05-17 01:19:11.000000', NULL, 1),
(721930, 76790, 18098, '<td valign="top">Nice shot.  The little rodent is cute and the colors are nice.</td>', 'Nice shot.  The little rodent is cute and the colors are nice.', '2004-05-17 01:20:42.000000', NULL, 1),
(721932, 77137, 18098, '<td valign="top">Beautiful colors.</td>', 'Beautiful colors.', '2004-05-17 01:20:58.000000', NULL, 1),
(721935, 76970, 17166, '<td valign="top">Yikes, stunning subject (no pun intended).  Definately a photo that grabbed my attention.  The rust and other details in the ball look way oversharpened, though.</td>', 'Yikes, stunning subject (no pun intended).  Definately a photo that grabbed my attention.  The rust and other details in the ball look way oversharpened, though.', '2004-05-17 01:21:07.000000', NULL, 1),
(721941, 76857, 17166, '<td valign="top">Great composition.  Really like the way this guy is posed and lit.</td>', 'Great composition.  Really like the way this guy is posed and lit.', '2004-05-17 01:22:33.000000', NULL, 1),
(721944, 76704, 21367, '<td valign="top">For me the lighting is a little harsh around the center, where color is lost.  Still a very interesting shot.  Nice detail and clarity.</td>', 'For me the lighting is a little harsh around the center, where color is lost.  Still a very interesting shot.  Nice detail and clarity.', '2004-05-17 01:22:49.000000', NULL, 1),
(721945, 77109, 17166, '<td valign="top">Really like how the little background flower is placed in the corner - gives some life and action to the image.</td>', 'Really like how the little background flower is placed in the corner - gives some life and action to the image.', '2004-05-17 01:24:03.000000', NULL, 1),
(721949, 77177, 21367, '<td valign="top">Nice detail in the center of the flower, I think I might have chose a more natural (earthy) background color.  The blue seems to be too bold.</td>', 'Nice detail in the center of the flower, I think I might have chose a more natural (earthy) background color.  The blue seems to be too bold.', '2004-05-17 01:24:51.000000', NULL, 1),
(721950, 77048, 17166, '<td valign="top">Great choice of subject matter.  The centered composition really makes this feel serene and balanced.</td>', 'Great choice of subject matter.  The centered composition really makes this feel serene and balanced.', '2004-05-17 01:25:16.000000', NULL, 1),
(721952, 76782, 21367, '<td valign="top">Very nice, good dof</td>', 'Very nice, good dof', '2004-05-17 01:27:13.000000', NULL, 1),
(721955, 76695, 17166, '<td valign="top">Nice, peaceful subject that''s enhanced by centered composition.  Wish there was a bit more dynamic range, or that at least the gazebo was darker, so that it popped more.</td>', 'Nice, peaceful subject that''s enhanced by centered composition.  Wish there was a bit more dynamic range, or that at least the gazebo was darker, so that it popped more.', '2004-05-17 01:28:05.000000', NULL, 1),
(721960, 76947, 21367, '<td valign="top">This is very cool, space age looking.  I like it.</td>', 'This is very cool, space age looking.  I like it.', '2004-05-17 01:30:36.000000', NULL, 1),
(721962, 76990, 20786, '<td valign="top">Very cool...Great lines and shadows. I really like the composition.</td>', 'Very cool...Great lines and shadows. I really like the composition.', '2004-05-17 01:31:00.000000', NULL, 1),
(721964, 76389, 20786, '<td valign="top">Very pretty. I like the random droplets on the repeating pattern of the  petals. I think a little more light at the bottom would make this image great.</td>', 'Very pretty. I like the random droplets on the repeating pattern of the  petals. I think a little more light at the bottom would make this image great.', '2004-05-17 01:33:25.000000', NULL, 1),
(721969, 77184, 21367, '<td valign="top">Very nice,  I wish I could see a tad more detail in the drop and then again, I find it interesting that I can almost make something out in the drop but the background is solid.  May instead of removing the background I might have gaussian blurred it severly.  Still a very good.</td>', 'Very nice,  I wish I could see a tad more detail in the drop and then again, I find it interesting that I can almost make something out in the drop but the background is solid.  May instead of removing the background I might have gaussian blurred it severly.  Still a very good.', '2004-05-17 01:35:31.000000', NULL, 1),
(721978, 77132, 17166, '<td valign="top">I noticed that you chose to make this less than 640 pixels to reduce the amount of JPEG compression needed - and that you got it to 149.54KB.  That in itself is an achievement!  And, I think it was a good choice to preserve detail and minimize artifacts.  Beautiful subject that lends itself perfectly to this challenge, very nicely captured.</td>', 'I noticed that you chose to make this less than 640 pixels to reduce the amount of JPEG compression needed - and that you got it to 149.54KB.  That in itself is an achievement!  And, I think it was a good choice to preserve detail and minimize artifacts.  Beautiful subject that lends itself perfectly to this challenge, very nicely captured.', '2004-05-17 01:37:48.000000', NULL, 1),
(721983, 77131, 7485, '<td valign="top">The idea and composition is just great, but the chroma-noise is distracting, especially red-green in the upper right corner</td>', 'The idea and composition is just great, but the chroma-noise is distracting, especially red-green in the upper right corner', '2004-05-17 01:39:07.000000', NULL, 1),
(721985, 76966, 21367, '<td valign="top">Love the colors in this one.  Maybe a little better lighting in the center would make this a great picture.  (I won''t say anything about the bug who keeps drawing my attention to the right if you don''t)</td>', 'Love the colors in this one.  Maybe a little better lighting in the center would make this a great picture.  (I won''t say anything about the bug who keeps drawing my attention to the right if you don''t)', '2004-05-17 01:39:12.000000', NULL, 1),
(721986, 76273, 17166, '<td valign="top">Would also be a good entry for the "Horror Movie Poster" challenge - those things are ugly.  Great sharpness.</td>', 'Would also be a good entry for the "Horror Movie Poster" challenge - those things are ugly.  Great sharpness.', '2004-05-17 01:39:29.000000', NULL, 1),
(721989, 76961, 17166, '<td valign="top">Very creative, great depth of field control and placement of focus.  Really like this photo.</td>', 'Very creative, great depth of field control and placement of focus.  Really like this photo.', '2004-05-17 01:40:57.000000', NULL, 1),
(721991, 76293, 21367, '<td valign="top">Very nice, great perspective.</td>', 'Very nice, great perspective.', '2004-05-17 01:41:36.000000', NULL, 1),
(721992, 77032, 7485, '<td valign="top">Lighting is just amazing, surely you have a winner here</td>', 'Lighting is just amazing, surely you have a winner here', '2004-05-17 01:41:36.000000', NULL, 1),
(721994, 76965, 21367, '<td valign="top">I think B/W works very well here.   Nice shot.</td>', 'I think B/W works very well here.   Nice shot.', '2004-05-17 01:43:16.000000', NULL, 1),
(721995, 75755, 7485, '<td valign="top">Great colors, but the frame is waaaay to distracting</td>', 'Great colors, but the frame is waaaay to distracting', '2004-05-17 01:43:42.000000', NULL, 1),
(721996, 76743, 21367, '<td valign="top">Awesome, great colors and detail.</td>', 'Awesome, great colors and detail.', '2004-05-17 01:44:17.000000', NULL, 1),
(722000, 76672, 17166, '<td valign="top">Good use of leading lines.  Tower looks like it''s leaning slightly.  I think this would work better if it were more tightly cropped - the sky is fairly hazy and blah, so the less of it in the picture the better.  And perhaps a polarizing filter to darken the sky as well.</td>', 'Good use of leading lines.  Tower looks like it''s leaning slightly.  I think this would work better if it were more tightly cropped - the sky is fairly hazy and blah, so the less of it in the picture the better.  And perhaps a polarizing filter to darken the sky as well.', '2004-05-17 01:45:48.000000', NULL, 1),
(722001, 77057, 21367, '<td valign="top">Great Idea, what we don''t see is what we are trying to center on.  Great job.</td>', 'Great Idea, what we don''t see is what we are trying to center on.  Great job.', '2004-05-17 01:46:15.000000', NULL, 1),
(722002, 76740, 7485, '<td valign="top">Great composition and use of unusual colors, but the focus just isn''t quite there</td>', 'Great composition and use of unusual colors, but the focus just isn''t quite there', '2004-05-17 01:46:16.000000', NULL, 1),
(722003, 77009, 17166, '<td valign="top">Nice capture of a classic scene.  I find the tree on the right competes for attention as it''s significantly darker than most of the rest of the picture - it really pops out at me.  I think the photo would be improved if it were cropped out.</td>', 'Nice capture of a classic scene.  I find the tree on the right competes for attention as it''s significantly darker than most of the rest of the picture - it really pops out at me.  I think the photo would be improved if it were cropped out.', '2004-05-17 01:47:33.000000', NULL, 1),
(722005, 76274, 21367, '<td valign="top">Bingo...I think you got it going on here.  Excellent DOF keeping us in the center of your shot.  Great Job.</td>', 'Bingo...I think you got it going on here.  Excellent DOF keeping us in the center of your shot.  Great Job.', '2004-05-17 01:47:49.000000', NULL, 1),
(722006, 76458, 17166, '<td valign="top">Great border (if it is a border - I''m assuming it is).  Really enhances the image.</td>', 'Great border (if it is a border - I''m assuming it is).  Really enhances the image.', '2004-05-17 01:49:10.000000', NULL, 1),
(722009, 77005, 17166, '<td valign="top">Nice composition with good framing and leading lines.  I think this photo would be better if it had been taken with a much smaller aperture (greater f-stop) and longer shutter speed.  The small aperture would improve the depth of field anhd made the structure at the rear sharp, and the slow shutter speed would have blurred the fountain into nice, soft lines.</td>', 'Nice composition with good framing and leading lines.  I think this photo would be better if it had been taken with a much smaller aperture (greater f-stop) and longer shutter speed.  The small aperture would improve the depth of field anhd made the structure at the rear sharp, and the slow shutter speed would have blurred the fountain into nice, soft lines.', '2004-05-17 01:51:45.000000', NULL, 1),
(722013, 76945, 17166, '<td valign="top">With the sintle ray of sunshing shining right on the crucifix.  Great timing to capture at that moment.</td>', 'With the sintle ray of sunshing shining right on the crucifix.  Great timing to capture at that moment.', '2004-05-17 01:54:21.000000', NULL, 1),
(722014, 76085, 20210, '<td valign="top">This is perfect for this challenge.  Well done!  The lines leading the eye right into the center are great, and the flag is dead-on center.  Not to mention the great mood and inspiring message.</td>', 'This is perfect for this challenge.  Well done!  The lines leading the eye right into the center are great, and the flag is dead-on center.  Not to mention the great mood and inspiring message.', '2004-05-17 01:54:50.000000', NULL, 1),
(722015, 76995, 20210, '<td valign="top">The visual weight is a little high for a "centered" composition.  Great focus.  Not sure if I''m seeing a stem on the bottom or what.  But a very fine shot overall.</td>', 'The visual weight is a little high for a "centered" composition.  Great focus.  Not sure if I''m seeing a stem on the bottom or what.  But a very fine shot overall.', '2004-05-17 01:55:50.000000', NULL, 1),
(722017, 76753, 20210, '<td valign="top">the tree stands out almost too much for my tastes, but an ethereal result.</td>', 'the tree stands out almost too much for my tastes, but an ethereal result.', '2004-05-17 01:56:16.000000', NULL, 1),
(722018, 76621, 20210, '<td valign="top">nice shot.  doesn''t fit the theme much for me, and the focus could be a little better, I feel.</td>', 'nice shot.  doesn''t fit the theme much for me, and the focus could be a little better, I feel.', '2004-05-17 01:56:47.000000', NULL, 1),
(722020, 76329, 20210, '<td valign="top">The depth of field is a little shallow to do this one justice.  But a fortunate capture, for sure!</td>', 'The depth of field is a little shallow to do this one justice.  But a fortunate capture, for sure!', '2004-05-17 01:57:33.000000', NULL, 1),
(722022, 76604, 20210, '<td valign="top">great texture in the ceiling (I think that''s what we''re looking at).  If the light had been a little more symmetrical, the eye would be drawn even more to the center.</td>', 'great texture in the ceiling (I think that''s what we''re looking at).  If the light had been a little more symmetrical, the eye would be drawn even more to the center.', '2004-05-17 01:58:29.000000', NULL, 1),
(722023, 75846, 21367, '<td valign="top">Nice simple approach...I like it.</td>', 'Nice simple approach...I like it.', '2004-05-17 01:58:49.000000', NULL, 1),
(722024, 77056, 20210, '<td valign="top">nice shot, but doesn''t scream "centered" to me.  The subject isn''t quite centered, and the lines lead the eye up and down more than resting in the middle.</td>', 'nice shot, but doesn''t scream "centered" to me.  The subject isn''t quite centered, and the lines lead the eye up and down more than resting in the middle.', '2004-05-17 01:59:05.000000', NULL, 1),
(722027, 77169, 20210, '<td valign="top">Beautiful shot.  The colors, the expression on her face, and the effective centered composition.  Fantastic.</td>', 'Beautiful shot.  The colors, the expression on her face, and the effective centered composition.  Fantastic.', '2004-05-17 01:59:58.000000', NULL, 1),
(722029, 77141, 20210, '<td valign="top">Amazing.  I''m not sure what it is, but I''d hang it my wall for sure.  Great texture and perfect exposure.</td>', 'Amazing.  I''m not sure what it is, but I''d hang it my wall for sure.  Great texture and perfect exposure.', '2004-05-17 02:02:00.000000', NULL, 1),
(722031, 77177, 20210, '<td valign="top">the blue background is a little flat for me, and the harshness of it actually focuses my eye away from the center, which is otherwise lovely.</td>', 'the blue background is a little flat for me, and the harshness of it actually focuses my eye away from the center, which is otherwise lovely.', '2004-05-17 02:04:06.000000', NULL, 1),
(722033, 76574, 21367, '<td valign="top">I might have used a little more light from the front in order to pick up a little more detail right at the mouth of the flower.  Still a good shot.</td>', 'I might have used a little more light from the front in order to pick up a little more detail right at the mouth of the flower.  Still a good shot.', '2004-05-17 02:04:30.000000', NULL, 1),
(722035, 76209, 20210, '<td valign="top">the hilites on the right are pretty washed out, and are distracting from the beautiful capture in the center.  A very nice mood!</td>', 'the hilites on the right are pretty washed out, and are distracting from the beautiful capture in the center.  A very nice mood!', '2004-05-17 02:04:53.000000', NULL, 1),
(722036, 76208, 6388, '<td valign="top">brilliant.  love it.  quirky enough to go on my wall...and I don''t even know Sandi :)  I might have burned the ground a bit away from her feet just to highlight them a little, but that wouldn''t change the impact, it''s just a preference. great shot.<br/>P</td>', 'brilliant.  love it.  quirky enough to go on my wall...and I don''t even know Sandi :)  I might have burned the ground a bit away from her feet just to highlight them a little, but that wouldn''t change the impact, it''s just a preference. great shot.P', '2004-05-17 02:04:58.000000', NULL, 1),
(722037, 76818, 21367, '<td valign="top">Very nice detail in the center of this flower.  Good job.</td>', 'Very nice detail in the center of this flower.  Good job.', '2004-05-17 02:05:33.000000', NULL, 1),
(722041, 75755, 20210, '<td valign="top">odd border, and interesting that there''s no real centered focal subject.  Not sure it works for this challenge, but aesthetically nice.</td>', 'odd border, and interesting that there''s no real centered focal subject.  Not sure it works for this challenge, but aesthetically nice.', '2004-05-17 02:06:21.000000', NULL, 1),
(722044, 77131, 20210, '<td valign="top">clever!  A great capture.  Even with just a little of the eyes, you get the sense of curiosity that''s there.</td>', 'clever!  A great capture.  Even with just a little of the eyes, you get the sense of curiosity that''s there.', '2004-05-17 02:07:53.000000', NULL, 1),
(722046, 76361, 21367, '<td valign="top">Excellent detail, good DOF.</td>', 'Excellent detail, good DOF.', '2004-05-17 02:08:18.000000', NULL, 1),
(722049, 76938, 20210, '<td valign="top">beautiful reflection.  Sometimes overdone, but couldn''t be more appropriate for "centered composition"</td>', 'beautiful reflection.  Sometimes overdone, but couldn''t be more appropriate for "centered composition"', '2004-05-17 02:09:42.000000', NULL, 1),
(722050, 76633, 21367, '<td valign="top">Clean and Simple, great dof and the white background really pulls it all together.  Great job.</td>', 'Clean and Simple, great dof and the white background really pulls it all together.  Great job.', '2004-05-17 02:09:47.000000', NULL, 1),
(722051, 75927, 21367, '<td valign="top">Interesting shot, a lot of stuff going on here yet I''m drawn to the center.  I like it.</td>', 'Interesting shot, a lot of stuff going on here yet I''m drawn to the center.  I like it.', '2004-05-17 02:11:06.000000', NULL, 1),
(722052, 77005, 19952, '<td valign="top">Wow. What a great shot.</td>', 'Wow. What a great shot.', '2004-05-17 02:11:15.000000', NULL, 1),
(722053, 77003, 14499, '<td valign="top">Funny! I have the same sort of title :) "Wild Life Centre"</td>', 'Funny! I have the same sort of title :) "Wild Life Centre"', '2004-05-17 02:11:38.000000', NULL, 1),
(722054, 76168, 20210, '<td valign="top">A little perspective-shift, and this would have been dead-center, but it''s slightly tilted.</td>', 'A little perspective-shift, and this would have been dead-center, but it''s slightly tilted.', '2004-05-17 02:11:51.000000', NULL, 1),
(722059, 76408, 20210, '<td valign="top">the solid black on the left is a little distracting.  but a very fine portrait indeed!</td>', 'the solid black on the left is a little distracting.  but a very fine portrait indeed!', '2004-05-17 02:14:45.000000', NULL, 1),
(722062, 76292, 21367, '<td valign="top">Ok, nothing draws ones attention to the center of a picture like a yellow port-a-pottie.  Great Idea.</td>', 'Ok, nothing draws ones attention to the center of a picture like a yellow port-a-pottie.  Great Idea.', '2004-05-17 02:16:58.000000', NULL, 1),
(722063, 77032, 20210, '<td valign="top">great concept on this!  The gray halo around him is odd, especially near the feet.  Very high marks though for this shot.</td>', 'great concept on this!  The gray halo around him is odd, especially near the feet.  Very high marks though for this shot.', '2004-05-17 02:18:04.000000', NULL, 1),
(722065, 77039, 21367, '<td valign="top">Excellent capture, quite moody.  I think you got the light right so that we focus in the center.  Nice job.</td>', 'Excellent capture, quite moody.  I think you got the light right so that we focus in the center.  Nice job.', '2004-05-17 02:18:15.000000', NULL, 1),
(722070, 77138, 20210, '<td valign="top">the light rays really make this shot "centered".  Beautiful!</td>', 'the light rays really make this shot "centered".  Beautiful!', '2004-05-17 02:20:48.000000', NULL, 1),
(722073, 76728, 20210, '<td valign="top">very interesting idea!  insightful.  The execution could have been a lot cleaner, I think.  There is no sharpness to this shot, and all the reflections of the room are quite distracting.</td>', 'very interesting idea!  insightful.  The execution could have been a lot cleaner, I think.  There is no sharpness to this shot, and all the reflections of the room are quite distracting.', '2004-05-17 02:22:08.000000', NULL, 1),
(722075, 77022, 19952, '<td valign="top">Wow! Really amazing shot.</td>', 'Wow! Really amazing shot.', '2004-05-17 02:24:14.000000', NULL, 1),
(722077, 77129, 10268, '<td valign="top">It looks like you cut the background out.  If not, then something looks wrong.  I also think it''s a little bit too saturated.<br/> <br/>I like the composition though.</td>', 'It looks like you cut the background out.  If not, then something looks wrong.  I also think it''s a little bit too saturated. I like the composition though.', '2004-05-17 02:25:35.000000', NULL, 1),
(722079, 76597, 10268, '<td valign="top">More focus and sharpness I think would be nice.<br/> <br/>I like the colors though.</td>', 'More focus and sharpness I think would be nice. I like the colors though.', '2004-05-17 02:26:53.000000', NULL, 1),
(722082, 76599, 10268, '<td valign="top">Very nice.  I love the texture on the wall, and the contrasting colors.  Awesome.  8.</td>', 'Very nice.  I love the texture on the wall, and the contrasting colors.  Awesome.  8.', '2004-05-17 02:28:12.000000', NULL, 1),
(722084, 76273, 4767, '<td valign="top">Amazing photo!  Sharp, with eye-attracting colors and a subject that is quite unique!</td>', 'Amazing photo!  Sharp, with eye-attracting colors and a subject that is quite unique!', '2004-05-17 02:28:44.000000', NULL, 1),
(722085, 76775, 10268, '<td valign="top">I think I see a bunch of clone marks in the center left?  Very distracting.</td>', 'I think I see a bunch of clone marks in the center left?  Very distracting.', '2004-05-17 02:29:15.000000', NULL, 1),
(722087, 77131, 19952, '<td valign="top">Nice shot!</td>', 'Nice shot!', '2004-05-17 02:29:38.000000', NULL, 1),
