INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(722449, 76158, 5822, '<td valign="top">I like the contrasts of flesh and rock and tones here. Also love the high grain. Though subjects pose is different and interesting, not sure what it''s significance is.  Minor issue is the visible tracks on the floor.  This image sure leaves me thinking and returning. 9</td>', 'I like the contrasts of flesh and rock and tones here. Also love the high grain. Though subjects pose is different and interesting, not sure what it''s significance is.  Minor issue is the visible tracks on the floor.  This image sure leaves me thinking and returning. 9', '2004-05-17 08:07:24.000000', NULL, 1),
(722450, 76853, 7684, '<td valign="top">10.</td>', '10.', '2004-05-17 08:07:41.000000', NULL, 1),
(722452, 77138, 20992, '<td valign="top">This one is the winner for me. You did great, catching that light and that sphere, it feels like the sailor is in the eye of the storm where it is deadcalm, but holding on untill the storm brews up again! The man in the middle gives it an ''in your face'' kind of feeling, here, the composition works very well. I don''t like the crackled suit he is wearing, it feels like the suit is new and not worn much..it makes a gap in my imagination..The colour is perfect though, gives it that extra spooky kinda look..Love the colours, love the atmosphere and I think you did a great job with this composition!! - 10 !!</td>', 'This one is the winner for me. You did great, catching that light and that sphere, it feels like the sailor is in the eye of the storm where it is deadcalm, but holding on untill the storm brews up again! The man in the middle gives it an ''in your face'' kind of feeling, here, the composition works very well. I don''t like the crackled suit he is wearing, it feels like the suit is new and not worn much..it makes a gap in my imagination..The colour is perfect though, gives it that extra spooky kinda look..Love the colours, love the atmosphere and I think you did a great job with this composition!! - 10 !!', '2004-05-17 08:08:37.000000', NULL, 1),
(722453, 76259, 20577, '<td valign="top">I really like the picture and the title. Very creative. 10</td>', 'I really like the picture and the title. Very creative. 10', '2004-05-17 08:09:14.000000', NULL, 1),
(722454, 77114, 7684, '<td valign="top">8.</td>', '8.', '2004-05-17 08:09:14.000000', NULL, 1),
(722455, 77167, 5822, '<td valign="top">Wonderful composition, but flesh tones could use some color balancing to get rid of the yellow cast.</td>', 'Wonderful composition, but flesh tones could use some color balancing to get rid of the yellow cast.', '2004-05-17 08:09:38.000000', NULL, 1),
(722457, 76217, 20577, '<td valign="top">Good picture. I think it would have been better without the bugs. 7</td>', 'Good picture. I think it would have been better without the bugs. 7', '2004-05-17 08:10:35.000000', NULL, 1),
(722458, 77180, 7684, '<td valign="top">Nice Car... 9...</td>', 'Nice Car... 9...', '2004-05-17 08:10:40.000000', NULL, 1),
(722460, 76541, 9089, '<td valign="top">I was waiting for the dartboard shot, but was expecting 2 darts in the bullseye, not a watch.  Not sure how this picture makes me feel, since I can''t see the Dawn in the picture.  Nothing I can say is wrong with the picture, but it just doesn''t seem interesting to me.</td>', 'I was waiting for the dartboard shot, but was expecting 2 darts in the bullseye, not a watch.  Not sure how this picture makes me feel, since I can''t see the Dawn in the picture.  Nothing I can say is wrong with the picture, but it just doesn''t seem interesting to me.', '2004-05-17 08:11:19.000000', NULL, 1),
(722461, 77039, 20992, '<td valign="top">I like the foggy mysterious look on this photo, but it;s too dark for me in the foreground. The stripe on the road is not quite straight (it has a curve) and it bothers..a straight line into the fog would have been great! Also I think the trees on the side of the road don''t add up to the story, in a sense they''re even distracting, because my eyes tend to keep looking at them, while all you want to is my eyes to be drawn to the fog. Another crop would have been okay. All in all, not bad, but not good either for me...</td>', 'I like the foggy mysterious look on this photo, but it;s too dark for me in the foreground. The stripe on the road is not quite straight (it has a curve) and it bothers..a straight line into the fog would have been great! Also I think the trees on the side of the road don''t add up to the story, in a sense they''re even distracting, because my eyes tend to keep looking at them, while all you want to is my eyes to be drawn to the fog. Another crop would have been okay. All in all, not bad, but not good either for me...', '2004-05-17 08:11:53.000000', NULL, 1),
(722462, 76850, 7684, '<td valign="top">Pretty Colors... 10.</td>', 'Pretty Colors... 10.', '2004-05-17 08:12:14.000000', NULL, 1),
(722464, 77056, 5822, '<td valign="top">Wonderful composition and portrait. Lighting is very good. Only thing I could say to slightly widen your crop so that you don''t cut off one of the red bars in the bottom right. Well done!</td>', 'Wonderful composition and portrait. Lighting is very good. Only thing I could say to slightly widen your crop so that you don''t cut off one of the red bars in the bottom right. Well done!', '2004-05-17 08:12:25.000000', NULL, 1),
(722465, 77005, 7684, '<td valign="top">10.</td>', '10.', '2004-05-17 08:12:56.000000', NULL, 1),
(722466, 76968, 20577, '<td valign="top">Beautiful little girl. The picture is fuzzy.</td>', 'Beautiful little girl. The picture is fuzzy.', '2004-05-17 08:13:41.000000', NULL, 1),
(722467, 77027, 9089, '<td valign="top">Neat photo, but the head of the duck draws my focus away from the center.</td>', 'Neat photo, but the head of the duck draws my focus away from the center.', '2004-05-17 08:13:49.000000', NULL, 1),
(722468, 76874, 20992, '<td valign="top">nice colour, that red! The reflection on the red and the round figures just on the edges of the photo work fine for the composition..the reflection in the metre on the other hand is disturbing..it makes me want to look through the picture not at it.</td>', 'nice colour, that red! The reflection on the red and the round figures just on the edges of the photo work fine for the composition..the reflection in the metre on the other hand is disturbing..it makes me want to look through the picture not at it.', '2004-05-17 08:14:13.000000', NULL, 1),
(722470, 77141, 7684, '<td valign="top">Nice colors... 10...</td>', 'Nice colors... 10...', '2004-05-17 08:14:34.000000', NULL, 1),
(722471, 76965, 7684, '<td valign="top">8.</td>', '8.', '2004-05-17 08:15:30.000000', NULL, 1),
(722472, 77124, 7684, '<td valign="top">Nice idea. I like the colors and abstract view. 8.</td>', 'Nice idea. I like the colors and abstract view. 8.', '2004-05-17 08:16:58.000000', NULL, 1),
(722473, 76704, 5822, '<td valign="top">Really like the composition and color here, but find the flash too strong and harsh.</td>', 'Really like the composition and color here, but find the flash too strong and harsh.', '2004-05-17 08:17:08.000000', NULL, 1),
(722474, 76829, 20577, '<td valign="top">Creepy!</td>', 'Creepy!', '2004-05-17 08:17:14.000000', NULL, 1),
(722475, 76864, 20992, '<td valign="top">how cliche the roses and the waterdrops on them!  I don''t think this is a nice picture to look at, the composition doesn''t do the flowers well, and the black background doesn''t fit the colour of the roses.. Technically, I think it''s a pity that some roses in the circle are more lit than others..the rose in the middle is beautifully lit though! maybe without the others, only the rose in the middle would have been more nice to look at..then the kitsch (is that English?) would have worked for the photo..</td>', 'how cliche the roses and the waterdrops on them!  I don''t think this is a nice picture to look at, the composition doesn''t do the flowers well, and the black background doesn''t fit the colour of the roses.. Technically, I think it''s a pity that some roses in the circle are more lit than others..the rose in the middle is beautifully lit though! maybe without the others, only the rose in the middle would have been more nice to look at..then the kitsch (is that English?) would have worked for the photo..', '2004-05-17 08:17:31.000000', NULL, 1),
(722476, 77113, 7684, '<td valign="top">9.</td>', '9.', '2004-05-17 08:17:53.000000', NULL, 1),
(722477, 76991, 9089, '<td valign="top">Overblown highlights</td>', 'Overblown highlights', '2004-05-17 08:18:00.000000', NULL, 1),
(722478, 76538, 20577, '<td valign="top">Good twist on the challenge. 8</td>', 'Good twist on the challenge. 8', '2004-05-17 08:18:15.000000', NULL, 1),
(722480, 76791, 20992, '<td valign="top">the background is to gray and the trees don''t show much detail..the idea though works fine for me! I wonder why you made the picture black and white??</td>', 'the background is to gray and the trees don''t show much detail..the idea though works fine for me! I wonder why you made the picture black and white??', '2004-05-17 08:19:01.000000', NULL, 1),
(722482, 77109, 7684, '<td valign="top">7.</td>', '7.', '2004-05-17 08:19:39.000000', NULL, 1),
(722483, 76495, 5822, '<td valign="top">Very original and creative composition. Love the backlighting and nicely saturated color and the way you''ve captured the drop in the center.  Also like the way you''ve captured the rind and spray on the bottom. Very well done.</td>', 'Very original and creative composition. Love the backlighting and nicely saturated color and the way you''ve captured the drop in the center.  Also like the way you''ve captured the rind and spray on the bottom. Very well done.', '2004-05-17 08:19:41.000000', NULL, 1),
(722484, 76670, 20992, '<td valign="top">sharp, colourfull, centered, with macro''s centering the subject is natural..in this photo it does the trick again!</td>', 'sharp, colourfull, centered, with macro''s centering the subject is natural..in this photo it does the trick again!', '2004-05-17 08:19:42.000000', NULL, 1),
(722486, 75891, 7684, '<td valign="top">Nice Shot. 10.</td>', 'Nice Shot. 10.', '2004-05-17 08:21:11.000000', NULL, 1),
(722487, 77041, 9089, '<td valign="top">Seems like too many water droplets</td>', 'Seems like too many water droplets', '2004-05-17 08:21:15.000000', NULL, 1),
(722491, 76081, 20992, '<td valign="top">I know this picture has been done before (even I did it!) but yours is truly great! It shows so much detail and I love the cropping..everything is in place, you worked great together with nature! It resembles a mandala!<br/>The colours are great, very peacefull, love the lighting (how did you manage to get all..fluffies (don''t know the English word :P ) so white???<br/>Superb this...(I imagine the picture with a larg wooden frame)<br/> <br/>10!!!</td>', 'I know this picture has been done before (even I did it!) but yours is truly great! It shows so much detail and I love the cropping..everything is in place, you worked great together with nature! It resembles a mandala!The colours are great, very peacefull, love the lighting (how did you manage to get all..fluffies (don''t know the English word :P ) so white???Superb this...(I imagine the picture with a larg wooden frame) 10!!!', '2004-05-17 08:25:31.000000', NULL, 1),
(722493, 76208, 20992, '<td valign="top">somehow this picture keeps attracting me... at first I thought it was ridiculous; just two feet in a picture..but I must say, it is getting nicer and nicer to look at. The shadowing is great, it''s okay that there is this dark part on the bottom to give balance to the feet...you managed to make a centered composition off centre though (looking at the lines), but that''s okay! Good contrast, good picture!</td>', 'somehow this picture keeps attracting me... at first I thought it was ridiculous; just two feet in a picture..but I must say, it is getting nicer and nicer to look at. The shadowing is great, it''s okay that there is this dark part on the bottom to give balance to the feet...you managed to make a centered composition off centre though (looking at the lines), but that''s okay! Good contrast, good picture!', '2004-05-17 08:28:57.000000', NULL, 1),
(722495, 75755, 20992, '<td valign="top">this is not centered, this is overall composition! It is a moving picture, in the sense that it looks like the flowers are falling down..the picture is not sharp, too saturated and you did something to sharpen it, but it damaged your pixels..the border is strange..I like the colours, but the rest, I think, needs more improvement...</td>', 'this is not centered, this is overall composition! It is a moving picture, in the sense that it looks like the flowers are falling down..the picture is not sharp, too saturated and you did something to sharpen it, but it damaged your pixels..the border is strange..I like the colours, but the rest, I think, needs more improvement...', '2004-05-17 08:31:09.000000', NULL, 1),
(722496, 76697, 20992, '<td valign="top">it''s not sleeping, is it? :)<br/>that''s what you call dead centre! Even the surrounding is working with you, cause it is curling around the bee..The DOF is just a little too small...I would have liked to see the bee more in focus, and maybe a bit (teeny) more light on it..but the sharpness is great!</td>', 'it''s not sleeping, is it? :)that''s what you call dead centre! Even the surrounding is working with you, cause it is curling around the bee..The DOF is just a little too small...I would have liked to see the bee more in focus, and maybe a bit (teeny) more light on it..but the sharpness is great!', '2004-05-17 08:32:59.000000', NULL, 1),
(722498, 76775, 20992, '<td valign="top">what''s that in the background????? the clutters are disturbing me..my eyes keep going over there, and miss that lovely simple tulip..another bakcground would have been fine..</td>', 'what''s that in the background????? the clutters are disturbing me..my eyes keep going over there, and miss that lovely simple tulip..another bakcground would have been fine..', '2004-05-17 08:34:53.000000', NULL, 1),
(722499, 76495, 20992, '<td valign="top">looks like a commercial!! The colours are fine, but I think it''s just too small cropped on the edges and too big on the upper and bottom site..maybe a light from the site would have lit up the orange, making it more sparkling orange on the sites!!</td>', 'looks like a commercial!! The colours are fine, but I think it''s just too small cropped on the edges and too big on the upper and bottom site..maybe a light from the site would have lit up the orange, making it more sparkling orange on the sites!!', '2004-05-17 08:37:41.000000', NULL, 1),
(722500, 76686, 20992, '<td valign="top">lovely romantic soft colours..you managed to give the photo that softness of the flower, good job!!</td>', 'lovely romantic soft colours..you managed to give the photo that softness of the flower, good job!!', '2004-05-17 08:38:19.000000', NULL, 1),
(722501, 77108, 9089, '<td valign="top">Difficult to see whatever it is out there, only things I can make out are the 4 birds circling.</td>', 'Difficult to see whatever it is out there, only things I can make out are the 4 birds circling.', '2004-05-17 08:38:35.000000', NULL, 1),
(722503, 76968, 20992, '<td valign="top">lovely looking child, love the look in her eyes, but it''s a pity that she moved, so the sharpness is gone.. also the red apples in the background distract the attention from the girl..</td>', 'lovely looking child, love the look in her eyes, but it''s a pity that she moved, so the sharpness is gone.. also the red apples in the background distract the attention from the girl..', '2004-05-17 08:39:51.000000', NULL, 1),
(722504, 76622, 2764, '<td valign="top">ummm I like it. except for the yellow center.  would it have been better black? 7</td>', 'ummm I like it. except for the yellow center.  would it have been better black? 7', '2004-05-17 08:41:44.000000', NULL, 1),
(722505, 76973, 5822, '<td valign="top">Beautiful subject, but wish you hadn''t used such harsh lighting as it''s created glare and deep shadow at the bottom.</td>', 'Beautiful subject, but wish you hadn''t used such harsh lighting as it''s created glare and deep shadow at the bottom.', '2004-05-17 08:42:04.000000', NULL, 1),
(722507, 77023, 9089, '<td valign="top">Like this one, but need to clone out the light on the side because it distracts from the quality of the photo.</td>', 'Like this one, but need to clone out the light on the side because it distracts from the quality of the photo.', '2004-05-17 08:48:47.000000', NULL, 1),
(722509, 76741, 14401, '<td valign="top">Cute.  Fuzzy.  Not much more I can say, though.  How do you critique a photo of someone''s child or pet?  Unless there is something really spectacular going on, there isn''t much to hold the interest of someone to whom the subject is not significant.</td>', 'Cute.  Fuzzy.  Not much more I can say, though.  How do you critique a photo of someone''s child or pet?  Unless there is something really spectacular going on, there isn''t much to hold the interest of someone to whom the subject is not significant.', '2004-05-17 08:49:37.000000', NULL, 1),
(722511, 77180, 9089, '<td valign="top">The center of focus for the picture to me is the steering wheel, had to look at your title to know you were wanting it to be the gear shift, but there is not enough in the gear shift to make it stand out to be the center of focus.  Beautiful car and photo besides that though.</td>', 'The center of focus for the picture to me is the steering wheel, had to look at your title to know you were wanting it to be the gear shift, but there is not enough in the gear shift to make it stand out to be the center of focus.  Beautiful car and photo besides that though.', '2004-05-17 08:53:56.000000', NULL, 1),
(722512, 76919, 9089, '<td valign="top">Made me smile :-)</td>', 'Made me smile :-)', '2004-05-17 08:54:47.000000', NULL, 1),
