(725338, 76564, 19608, '<td valign="top">Beautiful eye under good lighting.  Exposure is right on.   Would have a bit more impact if the model were looking straight at the lens.  One of the better entires for sure.</td>', 'Beautiful eye under good lighting.  Exposure is right on.   Would have a bit more impact if the model were looking straight at the lens.  One of the better entires for sure.', '2004-05-18 22:34:07.000000', NULL, 1),
(725339, 76400, 13158, '<td valign="top">Very cute expression.  Centered composition definitely works great here!</td>', 'Very cute expression.  Centered composition definitely works great here!', '2004-05-18 22:35:17.000000', NULL, 1),
(725340, 77022, 11518, '<td valign="top">spooky shot.</td>', 'spooky shot.', '2004-05-18 22:35:33.000000', NULL, 1),
(725344, 76829, 21367, '<td valign="top">Very nice.  Lighting, detail and composition are excellent.</td>', 'Very nice.  Lighting, detail and composition are excellent.', '2004-05-18 22:39:34.000000', NULL, 1),
(725345, 77104, 19608, '<td valign="top">The overcast lighting really punched up the colors.  Nice variety in the "pie-shaped" areas. You get an extra point for finding something that most people woukd just pass by without another thought.  Minor suggestion:  try to avoid the bright objects right on the border (green leaf at botttom and orange/green leaf on right edge).  They lead the viewer out of the image.  A very minor suggestion - not a point reducer!  Nice job.</td>', 'The overcast lighting really punched up the colors.  Nice variety in the "pie-shaped" areas. You get an extra point for finding something that most people woukd just pass by without another thought.  Minor suggestion:  try to avoid the bright objects right on the border (green leaf at botttom and orange/green leaf on right edge).  They lead the viewer out of the image.  A very minor suggestion - not a point reducer!  Nice job.', '2004-05-18 22:40:10.000000', NULL, 1),
(725347, 77102, 21367, '<td valign="top">This is most excellent.   Color, lighting and composition give this a nice moody effect.  Wouldn''t change a thing.  Great job.</td>', 'This is most excellent.   Color, lighting and composition give this a nice moody effect.  Wouldn''t change a thing.  Great job.', '2004-05-18 22:41:24.000000', NULL, 1),
(725349, 77115, 19608, '<td valign="top">Fun!  It''s a wonderful and colorful setup with great exposure - producing a nice feel.  My on;y complaint is that your model doesn''t exactly portray the feeling it deserves.  Evenso, it''s one of the stonger enties.</td>', 'Fun!  It''s a wonderful and colorful setup with great exposure - producing a nice feel.  My on;y complaint is that your model doesn''t exactly portray the feeling it deserves.  Evenso, it''s one of the stonger enties.', '2004-05-18 22:43:27.000000', NULL, 1),
(725352, 76335, 21367, '<td valign="top">Very good.  This plays well with the challenge.  I like the absence of any bright colors here, but it might have worked well with a bright flower in the black vase.  <br/>Great Job.</td>', 'Very good.  This plays well with the challenge.  I like the absence of any bright colors here, but it might have worked well with a bright flower in the black vase.  Great Job.', '2004-05-18 22:46:11.000000', NULL, 1),
(725353, 76538, 21367, '<td valign="top">Quite provacitive, well staged shot.  I may have gone with a little more front lighting to throw more emphasis on the victims head.  Also I think this would have worked better in B/W for a more journalistic approach.  Just my thoughts, still a very interesting shot (pardon the pun).</td>', 'Quite provacitive, well staged shot.  I may have gone with a little more front lighting to throw more emphasis on the victims head.  Also I think this would have worked better in B/W for a more journalistic approach.  Just my thoughts, still a very interesting shot (pardon the pun).', '2004-05-18 22:51:17.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(725354, 76982, 19608, '<td valign="top">Perfect color combination.  That green really makes the orange bug jump right out of the frame.  Your focus on the critter is deadly right on.</td>', 'Perfect color combination.  That green really makes the orange bug jump right out of the frame.  Your focus on the critter is deadly right on.', '2004-05-18 22:52:50.000000', NULL, 1),
(725355, 76932, 19608, '<td valign="top">Aren''t they marvelous birds?!  Great colors, very centered and dramatic.  The only thing I''d prefer a bit different is the ground.  It would be better on green grass or a darker colored "something."</td>', 'Aren''t they marvelous birds?!  Great colors, very centered and dramatic.  The only thing I''d prefer a bit different is the ground.  It would be better on green grass or a darker colored "something."', '2004-05-18 22:55:23.000000', NULL, 1),
(725358, 76272, 19608, '<td valign="top">Nice pastel colors against a perfect dark background.  The "fallen off" stamen on the lower leaf is a great touch.  It''s a bit soft.</td>', 'Nice pastel colors against a perfect dark background.  The "fallen off" stamen on the lower leaf is a great touch.  It''s a bit soft.', '2004-05-18 22:57:47.000000', NULL, 1),
(725359, 77089, 21367, '<td valign="top">Lovely shot, nice dof.  In this situation I might have picked the leaf that is casting the shadow on the front two (center) flowers.  It is somewhat distracting and the shadow it casts is blocking the detail that we may otherwise see in the center of the picture.   Good shot.</td>', 'Lovely shot, nice dof.  In this situation I might have picked the leaf that is casting the shadow on the front two (center) flowers.  It is somewhat distracting and the shadow it casts is blocking the detail that we may otherwise see in the center of the picture.   Good shot.', '2004-05-18 22:59:31.000000', NULL, 1),
(725363, 77058, 19608, '<td valign="top">Ah, another original idea!   Nice colors and textures - definitely centered.  Great as is, but if you want to add some points - figure out a way to make it less static.  Perhaps some dust of talc taken right as the ball hit the glove? (simulated of course.)   Keep up the good work.</td>', 'Ah, another original idea!   Nice colors and textures - definitely centered.  Great as is, but if you want to add some points - figure out a way to make it less static.  Perhaps some dust of talc taken right as the ball hit the glove? (simulated of course.)   Keep up the good work.', '2004-05-18 23:05:55.000000', NULL, 1),
(725368, 76144, 6597, '<td valign="top">Beautiful colors make this a stronger photo was these the real colors doesn''t matter       8</td>', 'Beautiful colors make this a stronger photo was these the real colors doesn''t matter       8', '2004-05-18 23:10:29.000000', NULL, 1),
(725372, 76488, 19608, '<td valign="top">Nice lighting and shadows, but I''m afraid the image doesn''t hold my attention.</td>', 'Nice lighting and shadows, but I''m afraid the image doesn''t hold my attention.', '2004-05-18 23:11:52.000000', NULL, 1),
(725373, 76847, 1135, '<td valign="top">Nice color. I may have cloned out the little hot spot on the green garbage can. Did I say that I liked the color? Very Nice.</td>', 'Nice color. I may have cloned out the little hot spot on the green garbage can. Did I say that I liked the color? Very Nice.', '2004-05-18 23:12:34.000000', NULL, 1),
(725375, 76965, 1135, '<td valign="top">Looks like hair growing out of the plan. Good focus and DOF. I would like to see this in color too. Nice Job.</td>', 'Looks like hair growing out of the plan. Good focus and DOF. I would like to see this in color too. Nice Job.', '2004-05-18 23:14:28.000000', NULL, 1),
(725376, 77149, 19608, '<td valign="top">This images produces a calming influence.  Soft lighting, soft colors.  Seems like the building isn''t quite level and the sky draws a lot of un-needed attention.</td>', 'This images produces a calming influence.  Soft lighting, soft colors.  Seems like the building isn''t quite level and the sky draws a lot of un-needed attention.', '2004-05-18 23:15:21.000000', NULL, 1),
(725379, 76805, 13305, '<td valign="top">I''d like this more if there were something vaguely visible near the extreme end of the fence, and/or with less sky.</td>', 'I''d like this more if there were something vaguely visible near the extreme end of the fence, and/or with less sky.', '2004-05-18 23:16:53.000000', NULL, 1),
(725383, 77176, 13305, '<td valign="top">Nicely done.  The BW really compliments the pic.  My only problem is the figure seems to be almost overexposed,  try shooting at a different time of day when the sun is not quite so straight down.</td>', 'Nicely done.  The BW really compliments the pic.  My only problem is the figure seems to be almost overexposed,  try shooting at a different time of day when the sun is not quite so straight down.', '2004-05-18 23:18:32.000000', NULL, 1),
(725384, 76068, 19608, '<td valign="top">Wake up - you''re gonna flunk!  Great composition and lighting.  Love the text that''s showing at the bottom and the drool-like whatever from the mouth.</td>', 'Wake up - you''re gonna flunk!  Great composition and lighting.  Love the text that''s showing at the bottom and the drool-like whatever from the mouth.', '2004-05-18 23:18:54.000000', NULL, 1),
(725386, 76968, 1135, '<td valign="top">Very cute little girl and I really like the composition, color and the expression that you captured. There is something odd around her mouth and nose though, almost looks like a double exposure. Camera shake maybe?</td>', 'Very cute little girl and I really like the composition, color and the expression that you captured. There is something odd around her mouth and nose though, almost looks like a double exposure. Camera shake maybe?', '2004-05-18 23:19:30.000000', NULL, 1),
(725387, 77032, 13305, '<td valign="top">Interesting pic to say the least.  I''d like to hear how it was done.  Maybe just a little light on the subject, but I think it''s pretty good as is.</td>', 'Interesting pic to say the least.  I''d like to hear how it was done.  Maybe just a little light on the subject, but I think it''s pretty good as is.', '2004-05-18 23:20:38.000000', NULL, 1),
(725390, 77032, 19608, '<td valign="top">Wonderful lighting, exposure and timing!  Lighting gives it a very mysterious yet intense quality.  With this subtle lighting - this is one case where the border has to go!  I know it''s just a thin line but your image with be better without it.</td>', 'Wonderful lighting, exposure and timing!  Lighting gives it a very mysterious yet intense quality.  With this subtle lighting - this is one case where the border has to go!  I know it''s just a thin line but your image with be better without it.', '2004-05-18 23:22:12.000000', NULL, 1),
(725391, 77179, 13305, '<td valign="top">The plastic spider and the blurred background tend to make me loose interest quickly.  Back out further and add some more color.</td>', 'The plastic spider and the blurred background tend to make me loose interest quickly.  Back out further and add some more color.', '2004-05-18 23:22:58.000000', NULL, 1),
(725393, 76343, 1135, '<td valign="top">Nice color on the grass and awesome structure. Where is this? Can you go inside? Very intriguing.</td>', 'Nice color on the grass and awesome structure. Where is this? Can you go inside? Very intriguing.', '2004-05-18 23:23:26.000000', NULL, 1),
(725395, 77115, 13305, '<td valign="top">Interesting use of desaturation in the center.  I think I''d prefer leave the color in for a "Where''s Waldo" type effect.</td>', 'Interesting use of desaturation in the center.  I think I''d prefer leave the color in for a "Where''s Waldo" type effect.', '2004-05-18 23:24:45.000000', NULL, 1),
(725398, 76961, 13305, '<td valign="top">I like the idea.  I think a different lighting scheme would look better.  Maybe from above.  Kudos to the model for being patient.</td>', 'I like the idea.  I think a different lighting scheme would look better.  Maybe from above.  Kudos to the model for being patient.', '2004-05-18 23:25:53.000000', NULL, 1),
(725403, 77039, 1135, '<td valign="top">Very mysterious and good job getting the exposure just right. This would look great hanging on the wall.</td>', 'Very mysterious and good job getting the exposure just right. This would look great hanging on the wall.', '2004-05-18 23:26:38.000000', NULL, 1),
(725405, 76974, 21367, '<td valign="top">Very nice calm looking situation.  Nice Capture.  I might have brought the levels just a little bit on the bushes behind your subject to throw a little more emphasis on the person as a whole.   The bright legs and arms stand out nicely in this shot.  The dark top goes well against the bench but seems to disappear along with the subjects hair around bushes.  Still an well composed shot.</td>', 'Very nice calm looking situation.  Nice Capture.  I might have brought the levels just a little bit on the bushes behind your subject to throw a little more emphasis on the person as a whole.   The bright legs and arms stand out nicely in this shot.  The dark top goes well against the bench but seems to disappear along with the subjects hair around bushes.  Still an well composed shot.', '2004-05-18 23:27:47.000000', NULL, 1),
(725407, 76829, 13305, '<td valign="top">Beautiful specimen. Well composed, well exposed.  You could put this in a textbook.</td>', 'Beautiful specimen. Well composed, well exposed.  You could put this in a textbook.', '2004-05-18 23:28:08.000000', NULL, 1),
(725409, 76976, 14620, '<td valign="top">Very interesting how the subject turns out to be negative space.  I really like this idea.  Nice use of light and shadows as well.</td>', 'Very interesting how the subject turns out to be negative space.  I really like this idea.  Nice use of light and shadows as well.', '2004-05-18 23:28:59.000000', NULL, 1),
(725412, 77137, 13305, '<td valign="top">Nicely done.  Great color on the fish, and good DOF.</td>', 'Nicely done.  Great color on the fish, and good DOF.', '2004-05-18 23:29:23.000000', NULL, 1),
(725414, 76945, 14620, '<td valign="top">Very nice lighting, really captures the tone of the photograph.</td>', 'Very nice lighting, really captures the tone of the photograph.', '2004-05-18 23:29:40.000000', NULL, 1),
(725416, 77180, 1135, '<td valign="top">My 13 year old son loves old cars; in fact he wants me to help him restore an old Mustang when he is 16. Very nice detail and the duotone works well for this shot. Good Job!</td>', 'My 13 year old son loves old cars; in fact he wants me to help him restore an old Mustang when he is 16. Very nice detail and the duotone works well for this shot. Good Job!', '2004-05-18 23:29:58.000000', NULL, 1),
(725418, 76990, 13305, '<td valign="top">Wow!   Really unique in the challenge and well done to boot.  Any other views?</td>', 'Wow!   Really unique in the challenge and well done to boot.  Any other views?', '2004-05-18 23:30:43.000000', NULL, 1),
(725421, 76961, 14620, '<td valign="top">Now that''s a new take on the typical flower shot! :)  Seems that the colors are somewhat muted.  I really like it.  Nice job!</td>', 'Now that''s a new take on the typical flower shot! :)  Seems that the colors are somewhat muted.  I really like it.  Nice job!', '2004-05-18 23:31:05.000000', NULL, 1),
(725423, 76695, 21072, '<td valign="top">Godot''s gazebo??  I thought it was a tree.<br/> <br/>Looks like a lonely place.....</td>', 'Godot''s gazebo??  I thought it was a tree. Looks like a lonely place.....', '2004-05-18 23:31:40.000000', NULL, 1),
(725424, 76006, 13305, '<td valign="top">Nice as the challenge goes.  Great expression.  I only wish you had all of her head in the frame (maybe it''s just me).</td>', 'Nice as the challenge goes.  Great expression.  I only wish you had all of her head in the frame (maybe it''s just me).', '2004-05-18 23:32:00.000000', NULL, 1),
(725427, 77182, 14620, '<td valign="top">Great perspective!   Makes it a much more intersting composition than just a straight on shot.  Quite original.</td>', 'Great perspective!   Makes it a much more intersting composition than just a straight on shot.  Quite original.', '2004-05-18 23:32:31.000000', NULL, 1),
(725428, 76855, 21072, '<td valign="top">Nice contrasts.  I can''t vote...but I like it.</td>', 'Nice contrasts.  I can''t vote...but I like it.', '2004-05-18 23:33:07.000000', NULL, 1),
(725429, 76990, 14620, '<td valign="top">Very dynamic effect for this shot.  Serves the subject well.</td>', 'Very dynamic effect for this shot.  Serves the subject well.', '2004-05-18 23:33:13.000000', NULL, 1),
(725432, 76743, 13305, '<td valign="top">Neat.  I think I''d prefer a little less DOF, make th leaves in the background blur even more. Add a label and you could use it for wine advertisement.</td>', 'Neat.  I think I''d prefer a little less DOF, make th leaves in the background blur even more. Add a label and you could use it for wine advertisement.', '2004-05-18 23:33:53.000000', NULL, 1),
(725434, 76850, 21072, '<td valign="top">Looks delicious.  Good idea :-)</td>', 'Looks delicious.  Good idea :-)', '2004-05-18 23:34:45.000000', NULL, 1),
(725436, 76829, 14620, '<td valign="top">This sooooo gives me the Heebee Jeebees!!  It freaks me out just to look at it.  Great clarity and intresting (but creepy) subject.   Sorry, that''s all I can write cause it''s creeping me out just to look at it anymore!! :-)  Nice job!!</td>', 'This sooooo gives me the Heebee Jeebees!!  It freaks me out just to look at it.  Great clarity and intresting (but creepy) subject.   Sorry, that''s all I can write cause it''s creeping me out just to look at it anymore!! :-)  Nice job!!', '2004-05-18 23:35:06.000000', NULL, 1),
(725439, 76379, 13305, '<td valign="top">I almost didn''t look closely at this pic.  It''s really very nice.  The flower is centered.  the light is directly from above, and just enough to illuminate the table the vase is on.  Very effective.</td>', 'I almost didn''t look closely at this pic.  It''s really very nice.  The flower is centered.  the light is directly from above, and just enough to illuminate the table the vase is on.  Very effective.', '2004-05-18 23:36:26.000000', NULL, 1),
(725442, 76217, 19608, '<td valign="top">Great exposure  - hard to do with a white flower.  Composition perfect for a dead-centered shot.  DoF well executed.  Are x-rated images allowed?</td>', 'Great exposure  - hard to do with a white flower.  Composition perfect for a dead-centered shot.  DoF well executed.  Are x-rated images allowed?', '2004-05-18 23:36:56.000000', NULL, 1),
(725446, 76981, 19608, '<td valign="top">Sepia works well for this subject.  Composition leads directly to the dead center position - but unfortunately - it''s just a dark void.</td>', 'Sepia works well for this subject.  Composition leads directly to the dead center position - but unfortunately - it''s just a dark void.', '2004-05-18 23:39:13.000000', NULL, 1),
(725448, 76158, 13305, '<td valign="top">Centered, yes.  Interessting? To say the least.  But this seems only to be a photo of a naked woman in nature.  She is slightly overexposed (photographically).  I think I would prefer either the color original or perhaps something more in the background for interest.  Perhaps some slave/fetish gear or some lash marks to add intersst.</td>', 'Centered, yes.  Interessting? To say the least.  But this seems only to be a photo of a naked woman in nature.  She is slightly overexposed (photographically).  I think I would prefer either the color original or perhaps something more in the background for interest.  Perhaps some slave/fetish gear or some lash marks to add intersst.', '2004-05-18 23:39:46.000000', NULL, 1),
(725454, 75927, 19608, '<td valign="top">Great idea  and centered for sure.  Nice use of DoF with the MB emblem and the model both sharp.  Picture this same image with a nice blue sky - perhaps almost the same blue as in the MB emblem... wow!</td>', 'Great idea  and centered for sure.  Nice use of DoF with the MB emblem and the model both sharp.  Picture this same image with a nice blue sky - perhaps almost the same blue as in the MB emblem... wow!', '2004-05-18 23:42:17.000000', NULL, 1),
(725456, 76292, 13305, '<td valign="top">This is an ok picture.  It lacks something.  Perhaps someone headed towards the port-a-potie? Better yet, someone peeking out of the door.</td>', 'This is an ok picture.  It lacks something.  Perhaps someone headed towards the port-a-potie? Better yet, someone peeking out of the door.', '2004-05-18 23:42:28.000000', NULL, 1),
(725458, 76970, 19608, '<td valign="top">Ouch!  Unique take on the challenge - original.  It shouts for a blue sky to help bring out the redish colors of the wrecking ball.</td>', 'Ouch!  Unique take on the challenge - original.  It shouts for a blue sky to help bring out the redish colors of the wrecking ball.', '2004-05-18 23:43:52.000000', NULL, 1),
(725460, 76408, 13305, '<td valign="top">Excellent portrait.  I like her smile and the twinkle in her eyes.  The way her head is cocked really takes away the years.  Good Shot.</td>', 'Excellent portrait.  I like her smile and the twinkle in her eyes.  The way her head is cocked really takes away the years.  Good Shot.', '2004-05-18 23:45:04.000000', NULL, 1),
(725466, 77177, 19608, '<td valign="top">Soothing colors, nice composition.  The green leaves on the left add some dynamic interest.  It''s too bad there wasn''t a slight ripple in the water - think it would be a bit easir to read.</td>', 'Soothing colors, nice composition.  The green leaves on the left add some dynamic interest.  It''s too bad there wasn''t a slight ripple in the water - think it would be a bit easir to read.', '2004-05-18 23:46:51.000000', NULL, 1),
(725468, 76633, 13305, '<td valign="top">Marvelous pic.  The detail in the water drops is perfect.  Only 1 minor problem,  the background seems to be overexposed.  This might be because of the lighting or because of the material you used for the background.  Nice DOF.</td>', 'Marvelous pic.  The detail in the water drops is perfect.  Only 1 minor problem,  the background seems to be overexposed.  This might be because of the lighting or because of the material you used for the background.  Nice DOF.', '2004-05-18 23:47:07.000000', NULL, 1),
(725474, 76274, 10128, '<td valign="top">Best I''ve seen</td>', 'Best I''ve seen', '2004-05-18 23:49:32.000000', NULL, 1),
(725476, 76740, 13305, '<td valign="top">Very nice portrait.  I like the way the lipstick/makeup picked up the light. It may be just me, but the eyes are sort of uneven.  Good, Effective crop too. I''d leave it like it is.</td>', 'Very nice portrait.  I like the way the lipstick/makeup picked up the light. It may be just me, but the eyes are sort of uneven.  Good, Effective crop too. I''d leave it like it is.', '2004-05-18 23:49:47.000000', NULL, 1),
(725479, 76846, 19608, '<td valign="top">It''s definitely in the center  but I''m not grasping much else.</td>', 'It''s definitely in the center  but I''m not grasping much else.', '2004-05-18 23:50:32.000000', NULL, 1),
(725481, 75934, 13305, '<td valign="top">Looks like a post card almost.  I like the colors, the reflection adds the perfect touch.  Even the crane adds to the entire effect. Did you get any shots from 5-10 minutes earlier? A little more red in the sunset would add lots of drama.</td>', 'Looks like a post card almost.  I like the colors, the reflection adds the perfect touch.  Even the crane adds to the entire effect. Did you get any shots from 5-10 minutes earlier? A little more red in the sunset would add lots of drama.', '2004-05-18 23:51:36.000000', NULL, 1),
(725485, 76085, 21367, '<td valign="top">Very nice shot, a lot of detail here but it all draws/pushes me to the center.  High marks (and not because I''m a former jarhead).  Wish there was just a tad more sharpness to this, but that is most likely due to stuff a lot of detail in a 640x640 area.  Bet the original is spectacular.  Great job.</td>', 'Very nice shot, a lot of detail here but it all draws/pushes me to the center.  High marks (and not because I''m a former jarhead).  Wish there was just a tad more sharpness to this, but that is most likely due to stuff a lot of detail in a 640x640 area.  Bet the original is spectacular.  Great job.', '2004-05-18 23:52:40.000000', NULL, 1),
(725493, 76881, 21367, '<td valign="top">Very Nice...I do find the lighting in the upper right (especially with the branch in it) a tad bit distracting.  Nice Floral, good macro.</td>', 'Very Nice...I do find the lighting in the upper right (especially with the branch in it) a tad bit distracting.  Nice Floral, good macro.', '2004-05-18 23:56:17.000000', NULL, 1),
(725498, 76961, 19608, '<td valign="top">The idea is original!  It''s centered but the agle and f-stop you chose made the focus hard to handle.</td>', 'The idea is original!  It''s centered but the agle and f-stop you chose made the focus hard to handle.', '2004-05-18 23:57:55.000000', NULL, 1),
(725506, 76988, 5822, '<td valign="top">Background seems dark, unnatural looking and overly processed.  It does, however, seperate your subjects well from the BG</td>', 'Background seems dark, unnatural looking and overly processed.  It does, however, seperate your subjects well from the BG', '2004-05-19 00:01:37.000000', NULL, 1),
(725552, 76802, 17837, '<td valign="top">This shot is outstanding! Leaves me at a loss for words... will comment when I can find those =0</td>', 'This shot is outstanding! Leaves me at a loss for words... will comment when I can find those =0', '2004-05-19 00:18:59.000000', NULL, 1),
(725561, 76577, 17837, '<td valign="top">Ive always wondered how one can get so close, even with long lenses, to shoot a bee...</td>', 'Ive always wondered how one can get so close, even with long lenses, to shoot a bee...', '2004-05-19 00:22:18.000000', NULL, 1),
(725585, 77163, 21367, '<td valign="top">awesome detail, great dof, over all a Great shot. Thumbs up on this one.</td>', 'awesome detail, great dof, over all a Great shot. Thumbs up on this one.', '2004-05-19 00:32:07.000000', NULL, 1),
(725586, 77137, 19608, '<td valign="top">Great lighting, great subject and colors that go so well together.  What more can you ask?</td>', 'Great lighting, great subject and colors that go so well together.  What more can you ask?', '2004-05-19 00:32:35.000000', NULL, 1),
(725588, 76959, 21367, '<td valign="top">Great shot, I wouldn''t change a thing.</td>', 'Great shot, I wouldn''t change a thing.', '2004-05-19 00:32:46.000000', NULL, 1),
(725594, 77109, 19608, '<td valign="top">Very nice flower - one of too many in the challenge.  The repeated shape in the bottom right corner is terrific.  Colors are a dream and work especially well together,</td>', 'Very nice flower - one of too many in the challenge.  The repeated shape in the bottom right corner is terrific.  Colors are a dream and work especially well together,', '2004-05-19 00:35:14.000000', NULL, 1),
(725598, 77118, 21367, '<td valign="top">Nice shot.  I think I would have tried to get a little more lighting in the center of the center flower to draw out a little more detail from that area.  dof is pretty good.</td>', 'Nice shot.  I think I would have tried to get a little more lighting in the center of the center flower to draw out a little more detail from that area.  dof is pretty good.', '2004-05-19 00:36:26.000000', NULL, 1),
(725601, 76855, 19608, '<td valign="top">Extreme color''  It was a bit disconcerting at first, but once the initial "shock" wore off - it grows on you.  Nice job.</td>', 'Extreme color''  It was a bit disconcerting at first, but once the initial "shock" wore off - it grows on you.  Nice job.', '2004-05-19 00:37:07.000000', NULL, 1),
(725615, 75755, 21367, '<td valign="top">Interesting view, I like the colors and the blurred effect.  I think in this case the wide frame draws one away from the center of the shot.  Very nice composition, perhaps a thinner frame or solid black frame would help to force the viewer down into the hole in the center of the picture.</td>', 'Interesting view, I like the colors and the blurred effect.  I think in this case the wide frame draws one away from the center of the shot.  Very nice composition, perhaps a thinner frame or solid black frame would help to force the viewer down into the hole in the center of the picture.', '2004-05-19 00:42:32.000000', NULL, 1),
(725654, 77164, 21367, '<td valign="top">You got it dead center I got to admit.  Technically a well organized picture with balanced negative/positive space, the dof is excellent.  Shot well taken.</td>', 'You got it dead center I got to admit.  Technically a well organized picture with balanced negative/positive space, the dof is excellent.  Shot well taken.', '2004-05-19 00:54:49.000000', NULL, 1),
(725657, 76856, 21367, '<td valign="top">Very nice.  Excellent colors and background.  This is a great shot.</td>', 'Very nice.  Excellent colors and background.  This is a great shot.', '2004-05-19 00:55:50.000000', NULL, 1),
(725661, 77143, 21367, '<td valign="top">Excellent Shot.  The colors all compliment each other, great dof.  I might not have cropped it so close on the top and bottom</td>', 'Excellent Shot.  The colors all compliment each other, great dof.  I might not have cropped it so close on the top and bottom', '2004-05-19 00:58:46.000000', NULL, 1),
(725760, 76947, 17166, '<td valign="top">This is an interesting composition and nicely toned.  But, it is suffering from a lot of jpeg artifacts (like the jagged diagonal lines and the jarring color gradient on the sphere).  Try saving with a higher quality setting (this picture only uses 53k and you''re allowed up to 150k for your entries).</td>', 'This is an interesting composition and nicely toned.  But, it is suffering from a lot of jpeg artifacts (like the jagged diagonal lines and the jarring color gradient on the sphere).  Try saving with a higher quality setting (this picture only uses 53k and you''re allowed up to 150k for your entries).', '2004-05-19 01:53:18.000000', NULL, 1),
(725769, 77033, 8054, '<td valign="top">This is an unusual color for a pinecone. Looks way too red in my opinion. Even the pine needles have a touch of red and there certainly is a lot in the background. Double check your color balance to see if that can be changed and if it accurately reflects what you truly saw.</td>', 'This is an unusual color for a pinecone. Looks way too red in my opinion. Even the pine needles have a touch of red and there certainly is a lot in the background. Double check your color balance to see if that can be changed and if it accurately reflects what you truly saw.', '2004-05-19 01:57:45.000000', NULL, 1),
(725777, 77110, 8054, '<td valign="top">Very striking building especially in that shade of red. Awesome details of the clouds as I can see every wisp. The lighthouse and the trees in the foreground are a different story as the lighthouse shows some compression artifacts (near the second window) and the middle tree''s leaves are a blur.</td>', 'Very striking building especially in that shade of red. Awesome details of the clouds as I can see every wisp. The lighthouse and the trees in the foreground are a different story as the lighthouse shows some compression artifacts (near the second window) and the middle tree''s leaves are a blur.', '2004-05-19 02:00:40.000000', NULL, 1),
(725781, 77154, 8054, '<td valign="top">Since the main subject is a silhouette, I feel this might have looked better as a b/w rather than color or maybe even sepia but that''s a personal opinion. Nice use of negative space, too.</td>', 'Since the main subject is a silhouette, I feel this might have looked better as a b/w rather than color or maybe even sepia but that''s a personal opinion. Nice use of negative space, too.', '2004-05-19 02:02:41.000000', NULL, 1),
(725786, 77048, 8054, '<td valign="top">The dark tones to this image lend well to the meditation title. Overall a bit too soft for my tastes as I would rather see sharper details in an image such as this.</td>', 'The dark tones to this image lend well to the meditation title. Overall a bit too soft for my tastes as I would rather see sharper details in an image such as this.', '2004-05-19 02:04:47.000000', NULL, 1),
(725791, 76856, 8054, '<td valign="top">Color balance seems strange and surreal, almost ethereal. Nice details in the wispy dandelion seeds and sense of wind spreading the seeds as indicated by your title. This particular image might look better in b/w.</td>', 'Color balance seems strange and surreal, almost ethereal. Nice details in the wispy dandelion seeds and sense of wind spreading the seeds as indicated by your title. This particular image might look better in b/w.', '2004-05-19 02:07:16.000000', NULL, 1),
(725795, 77176, 8054, '<td valign="top">Mannequin seems overexposed a bit. Window frame shows lots of texture and details and so does the screen.</td>', 'Mannequin seems overexposed a bit. Window frame shows lots of texture and details and so does the screen.', '2004-05-19 02:08:57.000000', NULL, 1),
(725801, 76603, 8054, '<td valign="top">Very nice attention to details. I can see just about every single wrinkle in the flower petals but the bottom petal is chopped off. You''ve probably heard that a million times already haven''t you?</td>', 'Very nice attention to details. I can see just about every single wrinkle in the flower petals but the bottom petal is chopped off. You''ve probably heard that a million times already haven''t you?', '2004-05-19 02:12:35.000000', NULL, 1),
(725808, 76400, 8054, '<td valign="top">Very well done selective desat. Excellent use of DOF. I would have cropped the bottom a bit tighter to eliminate that odd corner in the lower left and upped the contrast a bit with levels or curves. 7</td>', 'Very well done selective desat. Excellent use of DOF. I would have cropped the bottom a bit tighter to eliminate that odd corner in the lower left and upped the contrast a bit with levels or curves. 7', '2004-05-19 02:18:24.000000', NULL, 1),
(725813, 76980, 8054, '<td valign="top">Excellent details of both the log and the frog. Overall, it feels a bit overexposed but maybe it''s my eyes. The lighter colored wood is what I''m talking about as it just feels bright. I also think the top could use some trimming to just below the level of the small twig sticking out of the water. 7</td>', 'Excellent details of both the log and the frog. Overall, it feels a bit overexposed but maybe it''s my eyes. The lighter colored wood is what I''m talking about as it just feels bright. I also think the top could use some trimming to just below the level of the small twig sticking out of the water. 7', '2004-05-19 02:20:57.000000', NULL, 1),
(725824, 77043, 8054, '<td valign="top">Nice from a technical standpoint but isn''t the most thrilling entry (no offense).</td>', 'Nice from a technical standpoint but isn''t the most thrilling entry (no offense).', '2004-05-19 02:26:40.000000', NULL, 1),
(725832, 77180, 8054, '<td valign="top">Unusually sharp without (significant) halos which is quite impressive! Image is also just a bit bright for my liking. Nice choice going with sepia/duotone.</td>', 'Unusually sharp without (significant) halos which is quite impressive! Image is also just a bit bright for my liking. Nice choice going with sepia/duotone.', '2004-05-19 02:30:11.000000', NULL, 1),
(725842, 76952, 17148, '<td valign="top">very simple, like it</td>', 'very simple, like it', '2004-05-19 02:40:13.000000', NULL, 1),
(725843, 75983, 17148, '<td valign="top">like it, very clean and colorful</td>', 'like it, very clean and colorful', '2004-05-19 02:41:00.000000', NULL, 1),
(725844, 77138, 17148, '<td valign="top">Beautiful, this is a ribon winner</td>', 'Beautiful, this is a ribon winner', '2004-05-19 02:41:59.000000', NULL, 1),
(726127, 77029, 8522, '<td valign="top">Unusual black and white, would have prefered more detail in the highlights. There is too much contrast in this shot for my taste, meaning that shadow and highlight detail is lost. Very noisy. Ultimatedly not enough here to sustain my interest.</td>', 'Unusual black and white, would have prefered more detail in the highlights. There is too much contrast in this shot for my taste, meaning that shadow and highlight detail is lost. Very noisy. Ultimatedly not enough here to sustain my interest.', '2004-05-19 06:23:17.000000', NULL, 1),
(726128, 77176, 8522, '<td valign="top">Interesting shot... unfortunately your subject doesn''t quite stand out enough from the surroundings to draw my eye in. Burnt out highlights are unfortunate. Rest of the photo has some interesting textures, but this is part of the problem as they take attention away from the subject.</td>', 'Interesting shot... unfortunately your subject doesn''t quite stand out enough from the surroundings to draw my eye in. Burnt out highlights are unfortunate. Rest of the photo has some interesting textures, but this is part of the problem as they take attention away from the subject.', '2004-05-19 06:24:52.000000', NULL, 1),
(726129, 77153, 8522, '<td valign="top">Far too oversharpened and contrasty. Not enough here to keep me interested.</td>', 'Far too oversharpened and contrasty. Not enough here to keep me interested.', '2004-05-19 06:25:39.000000', NULL, 1),
(726131, 76965, 8522, '<td valign="top">Stunning picture, but the levels look a bit strange to me. I''d love to have seen the colour original. Colour would also help the background from not blending into the foreground subject in places. I think plenty of dodging and burning is required here... there''s plenty of shadow detail in your subject to be rescued, and the background needs to be darker in places.</td>', 'Stunning picture, but the levels look a bit strange to me. I''d love to have seen the colour original. Colour would also help the background from not blending into the foreground subject in places. I think plenty of dodging and burning is required here... there''s plenty of shadow detail in your subject to be rescued, and the background needs to be darker in places.', '2004-05-19 06:28:15.000000', NULL, 1),
(726133, 76897, 8522, '<td valign="top">Not really in the centre... especially when you consider the main point of focus is the red light at the top of the building. Picture is very noisy, which could have been fixed with NeatImage. Not really sure what you were trying to achieve with this picture.</td>', 'Not really in the centre... especially when you consider the main point of focus is the red light at the top of the building. Picture is very noisy, which could have been fixed with NeatImage. Not really sure what you were trying to achieve with this picture.', '2004-05-19 06:29:51.000000', NULL, 1),
(726135, 76577, 8522, '<td valign="top">Strunning, impressive dof. Great textures, composition, colours. Radius in USM looks like it was a little too large here though. Lots of noise... probably as the photo was taken at high ISO to improve the dof? I''m sure NeatImage could have improved the purple background in particular. Should do well.</td>', 'Strunning, impressive dof. Great textures, composition, colours. Radius in USM looks like it was a little too large here though. Lots of noise... probably as the photo was taken at high ISO to improve the dof? I''m sure NeatImage could have improved the purple background in particular. Should do well.', '2004-05-19 06:32:38.000000', NULL, 1),
(726136, 76540, 8522, '<td valign="top">Interesting portrait, but comes across as a bit of a snapshot. Noise levels here are huge... could NeatImage not help before resizing?</td>', 'Interesting portrait, but comes across as a bit of a snapshot. Noise levels here are huge... could NeatImage not help before resizing?', '2004-05-19 06:34:26.000000', NULL, 1),
(726140, 77163, 8522, '<td valign="top">Stunning... I''d have worked in PS on the eye a little to make the catchlight/reflections a little more appealing. Shame the top feather has been cropped off in your composition. Great dof. Wonderful expression captured. Surely portrait orientation would have worked better than landscape? Some dodging and burning requred to really make justice to this photo.</td>', 'Stunning... I''d have worked in PS on the eye a little to make the catchlight/reflections a little more appealing. Shame the top feather has been cropped off in your composition. Great dof. Wonderful expression captured. Surely portrait orientation would have worked better than landscape? Some dodging and burning requred to really make justice to this photo.', '2004-05-19 06:36:58.000000', NULL, 1),
(726141, 76599, 8522, '<td valign="top">Some great colours here, especially some of the blues. Love the rust in the doorway. Ultimately lacking something to raise it above the ordinary though.</td>', 'Some great colours here, especially some of the blues. Love the rust in the doorway. Ultimately lacking something to raise it above the ordinary though.', '2004-05-19 06:38:13.000000', NULL, 1),
(726143, 77003, 8522, '<td valign="top">Nice macro... unfortunately the bee/wasp doesn''t really stand out from his background which is a little too busy and cluttered.</td>', 'Nice macro... unfortunately the bee/wasp doesn''t really stand out from his background which is a little too busy and cluttered.', '2004-05-19 06:39:42.000000', NULL, 1),
(726144, 76728, 8522, '<td valign="top">Shame this is so blurred... I like the idea of motion blur here but would like to see some sharpness somewhere! Some great colours.</td>', 'Shame this is so blurred... I like the idea of motion blur here but would like to see some sharpness somewhere! Some great colours.', '2004-05-19 06:40:36.000000', NULL, 1),
(726148, 76144, 8522, '<td valign="top">Wonderful. Was this achieved in PS, as the colours are those of a rainbow from the inside out? I must try this on a centred rose.</td>', 'Wonderful. Was this achieved in PS, as the colours are those of a rainbow from the inside out? I must try this on a centred rose.', '2004-05-19 06:42:01.000000', NULL, 1),
(726169, 77032, 18450, '<td valign="top">love the creativity here, the colours, focus......everything</td>', 'love the creativity here, the colours, focus......everything', '2004-05-19 06:58:43.000000', NULL, 1),
(726179, 76973, 18450, '<td valign="top">lovely colours ....though the shell is completely central because of the design I found my focus drawn away from the centre</td>', 'lovely colours ....though the shell is completely central because of the design I found my focus drawn away from the centre', '2004-05-19 07:16:18.000000', NULL, 1),
(726181, 77137, 18450, '<td valign="top">beautiful colours</td>', 'beautiful colours', '2004-05-19 07:18:13.000000', NULL, 1),
(726194, 76262, 16126, '<td valign="top">Great colors! It seems slightly tilted to the right, and cropping could have been tighter to cut off the large dark areas left and right.</td>', 'Great colors! It seems slightly tilted to the right, and cropping could have been tighter to cut off the large dark areas left and right.', '2004-05-19 07:32:45.000000', NULL, 1),
(726197, 76762, 16126, '<td valign="top">Nice image, I like the smooth impression of the water. Don''t like the border though. Background seems a little bit out of focus, would have been better either sharp or much more blurred.</td>', 'Nice image, I like the smooth impression of the water. Don''t like the border though. Background seems a little bit out of focus, would have been better either sharp or much more blurred.', '2004-05-19 07:34:56.000000', NULL, 1),
(726199, 76952, 16126, '<td valign="top">Took me a while to figure out what this is, because not everything is in focus. Good thinking!</td>', 'Took me a while to figure out what this is, because not everything is in focus. Good thinking!', '2004-05-19 07:37:09.000000', NULL, 1),
(726202, 76633, 8522, '<td valign="top">Beautiful, clean composition. Very effective white background. Lovely shades of green. Effective use of water drops. Interesting subject. Should do well!</td>', 'Beautiful, clean composition. Very effective white background. Lovely shades of green. Effective use of water drops. Interesting subject. Should do well!', '2004-05-19 07:53:27.000000', NULL, 1),
(726214, 77001, 8522, '<td valign="top">Fits the challenge, but doesn''t do a lot for me. Too much going on in the background, there is no clear focal point for the eye to settle on.</td>', 'Fits the challenge, but doesn''t do a lot for me. Too much going on in the background, there is no clear focal point for the eye to settle on.', '2004-05-19 08:01:33.000000', NULL, 1),
(726217, 77107, 8522, '<td valign="top">Nice detail shot, the symmetry is spot on. Colours are perhaps a bit muted, maybe raise the gamma? Some lovely blues in the clock.</td>', 'Nice detail shot, the symmetry is spot on. Colours are perhaps a bit muted, maybe raise the gamma? Some lovely blues in the clock.', '2004-05-19 08:02:56.000000', NULL, 1),
(726221, 77136, 8522, '<td valign="top">Wonderful idea, very creative. Would be nice to have a tad more contrast in the shot. Great composition. I may have prefered this in colour.</td>', 'Wonderful idea, very creative. Would be nice to have a tad more contrast in the shot. Great composition. I may have prefered this in colour.', '2004-05-19 08:05:22.000000', NULL, 1),
(726224, 76538, 8522, '<td valign="top">Interesting take on challenge... although not normally a fan of word-play. Great special effects! Would be nice to have had more sharpness.</td>', 'Interesting take on challenge... although not normally a fan of word-play. Great special effects! Would be nice to have had more sharpness.', '2004-05-19 08:06:24.000000', NULL, 1),
(726225, 76621, 11895, '<td valign="top">a very nice, impactful shot but the background is much too dark, it takes away definition by blending with the black parts of the subject (tires and seat)</td>', 'a very nice, impactful shot but the background is much too dark, it takes away definition by blending with the black parts of the subject (tires and seat)', '2004-05-19 08:06:40.000000', NULL, 1),
(726228, 76775, 8522, '<td valign="top">I''m a bit baffled by what''s going on in this picture... what are the blobs above and to the left of the tulip? They look really odd. Lovely light on the tulip.</td>', 'I''m a bit baffled by what''s going on in this picture... what are the blobs above and to the left of the tulip? They look really odd. Lovely light on the tulip.', '2004-05-19 08:08:20.000000', NULL, 1),
(726231, 76874, 8522, '<td valign="top">Great idea, some great colours and the dial has a lot of character. Spoilt by the reflections and levels of glare though.</td>', 'Great idea, some great colours and the dial has a lot of character. Spoilt by the reflections and levels of glare though.', '2004-05-19 08:09:04.000000', NULL, 1),
(726235, 76590, 11895, '<td valign="top">nice photo, fits the challenge well, focus could be sharper, border looks gimmicky</td>', 'nice photo, fits the challenge well, focus could be sharper, border looks gimmicky', '2004-05-19 08:12:47.000000', NULL, 1),
(726239, 76947, 6999, '<td valign="top">Has  a weird sensation of not being absolutely symmetrical ... just enough to make it slightly unsettling to look at, like there''s some distortion somewhere. Colour saturation hasn''t been dealt with terribly well, lots of pixelation in the pinks around the brightest areas. Jaggedness from perhaps over-sharpening on the hard lines too. All that said, it has potential as a geometric image i think, but too many things interrupt the cleanness of the presentation for me. 4</td>', 'Has  a weird sensation of not being absolutely symmetrical ... just enough to make it slightly unsettling to look at, like there''s some distortion somewhere. Colour saturation hasn''t been dealt with terribly well, lots of pixelation in the pinks around the brightest areas. Jaggedness from perhaps over-sharpening on the hard lines too. All that said, it has potential as a geometric image i think, but too many things interrupt the cleanness of the presentation for me. 4', '2004-05-19 08:15:38.000000', NULL, 1),
(726243, 76952, 6999, '<td valign="top">Blunt, simple, and suitable to a centred composition. The light is almost ideal, although badly let doen by the indistinct end of the barrell - perhaps a little extra light there, from a reflector or even another light source would help. The extremely shallow depth of field helps in some ways, but it is so extreme as to miss the end-sight, and yet there isn''t enough detail in the very end of the barrell to hold attention for me. 5</td>', 'Blunt, simple, and suitable to a centred composition. The light is almost ideal, although badly let doen by the indistinct end of the barrell - perhaps a little extra light there, from a reflector or even another light source would help. The extremely shallow depth of field helps in some ways, but it is so extreme as to miss the end-sight, and yet there isn''t enough detail in the very end of the barrell to hold attention for me. 5', '2004-05-19 08:17:59.000000', NULL, 1),
(726247, 76818, 6999, '<td valign="top">Works compositionally, effectively a simple leading lines shot, but none the less effective for that. The glancing light is effective in rendering the shape and texture for the most part, but the image right petals have a muddy quality that might have been lifted with a little bounced fill-light perhaps. Not quite enough fascination to hold my interest for long, but a good shot all the same. 6</td>', 'Works compositionally, effectively a simple leading lines shot, but none the less effective for that. The glancing light is effective in rendering the shape and texture for the most part, but the image right petals have a muddy quality that might have been lifted with a little bounced fill-light perhaps. Not quite enough fascination to hold my interest for long, but a good shot all the same. 6', '2004-05-19 08:20:07.000000', NULL, 1),
(726250, 77181, 11895, '<td valign="top">too shallow DoF</td>', 'too shallow DoF', '2004-05-19 08:20:58.000000', NULL, 1),
(726252, 75934, 11895, '<td valign="top">beautiful shot, but this is Advanced Editing so I think I would hane cloned out the cranes and antennas (?) from the top of buildings</td>', 'beautiful shot, but this is Advanced Editing so I think I would hane cloned out the cranes and antennas (?) from the top of buildings', '2004-05-19 08:21:14.000000', NULL, 1),
(726254, 77111, 11895, '<td valign="top">too dark</td>', 'too dark', '2004-05-19 08:21:56.000000', NULL, 1),
(726257, 77149, 6999, '<td valign="top">why not crop out the entirety of the tree-trunk picture right? It would leave you with a genuinely centred composition, instead of the halfway-there shot, and would to my eye balance the composition more evenly. Not a bad image at all, but lacking in much real mood, either of drama, or gentleness, or peace. Perhaps needed a different light to caryy it off, or failing that more processing work to give it some punch. As it stands, it is fairly ordinary to me. 5</td>', 'why not crop out the entirety of the tree-trunk picture right? It would leave you with a genuinely centred composition, instead of the halfway-there shot, and would to my eye balance the composition more evenly. Not a bad image at all, but lacking in much real mood, either of drama, or gentleness, or peace. Perhaps needed a different light to caryy it off, or failing that more processing work to give it some punch. As it stands, it is fairly ordinary to me. 5', '2004-05-19 08:23:24.000000', NULL, 1),
(726262, 76980, 8522, '<td valign="top">Wonderful textures, I''d have liked a little more detail in the highlights. Lovely shades of green.</td>', 'Wonderful textures, I''d have liked a little more detail in the highlights. Lovely shades of green.', '2004-05-19 08:26:41.000000', NULL, 1),
(726267, 77167, 8522, '<td valign="top">Great portrait, if not entirely flattering! That is one worried looking boy... Great colours and saturation. Shame the tips of the fingers are chopped off.</td>', 'Great portrait, if not entirely flattering! That is one worried looking boy... Great colours and saturation. Shame the tips of the fingers are chopped off.', '2004-05-19 08:27:51.000000', NULL, 1),
(726270, 76622, 6999, '<td valign="top">Like Naif-school art, and not something that ever held very much appeal for me personally, and certainly not as photography, but there you go. Has a certain appeal in its irregularity I suppose, and well rendered for a very tricky medium given the size restrictions here. But I''m struggling to find good things to say about an image which I don''t frankly find anything to hold my interest for long in. 3</td>', 'Like Naif-school art, and not something that ever held very much appeal for me personally, and certainly not as photography, but there you go. Has a certain appeal in its irregularity I suppose, and well rendered for a very tricky medium given the size restrictions here. But I''m struggling to find good things to say about an image which I don''t frankly find anything to hold my interest for long in. 3', '2004-05-19 08:30:10.000000', NULL, 1),
(726272, 76855, 8522, '<td valign="top">I love those lanterns, and they work very well in this shot. Great composition and colours. Effective stock photo. Could do with perhaps slightly richer saturation.</td>', 'I love those lanterns, and they work very well in this shot. Great composition and colours. Effective stock photo. Could do with perhaps slightly richer saturation.', '2004-05-19 08:34:07.000000', NULL, 1),
(726279, 76919, 14603, '<td valign="top">Might not suit the people with the measuring tapes :) but I think it`s ideal for the challenge, a clever idea , well captured.</td>', 'Might not suit the people with the measuring tapes :) but I think it`s ideal for the challenge, a clever idea , well captured.', '2004-05-19 08:38:57.000000', NULL, 1),
(726281, 76408, 14603, '<td valign="top">Good portrait,I like the way the ladys` head is tilted (simple things which make a huge difference) Good clutter free background and nice complimentary colours in the clothing.<br/>Very well done.</td>', 'Good portrait,I like the way the ladys` head is tilted (simple things which make a huge difference) Good clutter free background and nice complimentary colours in the clothing.Very well done.', '2004-05-19 08:42:33.000000', NULL, 1),
(726300, 76772, 8522, '<td valign="top">Beautiful colours and textures. Exposure is just right. Something very satisfying about this shot.</td>', 'Beautiful colours and textures. Exposure is just right. Something very satisfying about this shot.', '2004-05-19 08:54:49.000000', NULL, 1),
(726301, 77162, 14603, '<td valign="top">Absolutely gorgeous wee dog...well wee just now :) <br/>Photo would have more impact for me if you got a little closer and captured mainly head and shoulders with just a little greenery ..concentrating on between the eyes for dead centre. However, there`s no saying how that would go down with the "dead centre brigade".</td>', 'Absolutely gorgeous wee dog...well wee just now :) Photo would have more impact for me if you got a little closer and captured mainly head and shoulders with just a little greenery ..concentrating on between the eyes for dead centre. However, there`s no saying how that would go down with the "dead centre brigade".', '2004-05-19 08:54:51.000000', NULL, 1),
(726306, 77158, 8522, '<td valign="top">Nice capture... I''d have used PS to bring out shadow detail in the Goose''s features. Possibly a little over-saturated. Not really centered, as the point of focus is the Goose''s eyes.</td>', 'Nice capture... I''d have used PS to bring out shadow detail in the Goose''s features. Possibly a little over-saturated. Not really centered, as the point of focus is the Goose''s eyes.', '2004-05-19 08:56:43.000000', NULL, 1),
(726309, 76932, 14603, '<td valign="top">I`ve got the feeling I`ve seen this fella before  :)<br/>Perfect subject for the challenge in my view..of course you realise some folks are going to be counting the eyes from the edge to the middle !<br/>Well done</td>', 'I`ve got the feeling I`ve seen this fella before  :)Perfect subject for the challenge in my view..of course you realise some folks are going to be counting the eyes from the edge to the middle !Well done', '2004-05-19 08:58:20.000000', NULL, 1),
(726322, 76969, 14603, '<td valign="top">Always interested in the bird shots..this looks like our Blackbird (which I think is called a Robin in America ??).<br/>Well centred but unfortunately the sharpness is missing..possibly because of digital zoom being used ??. Good capture though.</td>', 'Always interested in the bird shots..this looks like our Blackbird (which I think is called a Robin in America ??).Well centred but unfortunately the sharpness is missing..possibly because of digital zoom being used ??. Good capture though.', '2004-05-19 09:03:58.000000', NULL, 1),
(726330, 76965, 14603, '<td valign="top">Really like the tonal range of this image..great clarity too.</td>', 'Really like the tonal range of this image..great clarity too.', '2004-05-19 09:06:12.000000', NULL, 1),
(726341, 76968, 8522, '<td valign="top">Nice portrait, shame it''s so blurry. It looks like camera shake. Nicely exposed.</td>', 'Nice portrait, shame it''s so blurry. It looks like camera shake. Nicely exposed.', '2004-05-19 09:12:18.000000', NULL, 1),
(726343, 76994, 8522, '<td valign="top">Not sure that selective desat really brings anything to this picture. It looks more like a gimmick here. High levels of noise and nothing is particularly sharp. Composition seems a tad tilted.</td>', 'Not sure that selective desat really brings anything to this picture. It looks more like a gimmick here. High levels of noise and nothing is particularly sharp. Composition seems a tad tilted.', '2004-05-19 09:13:39.000000', NULL, 1),
(726355, 77014, 8522, '<td valign="top">Nice and simple... apple is well lit, high-key background works well. You really have captured the essence of this apple. I like the apple''s shadow.</td>', 'Nice and simple... apple is well lit, high-key background works well. You really have captured the essence of this apple. I like the apple''s shadow.', '2004-05-19 09:23:24.000000', NULL, 1),
(726357, 76682, 8522, '<td valign="top">I REALLY don''t like this border, which detracts heavily from the photo. I just can''t understand why it was used here. Flowers are very nice, background works very well. Great colours and saturation. Exposure is spot on. Have to take off points for that border though, as it stops me focusing on the photo.</td>', 'I REALLY don''t like this border, which detracts heavily from the photo. I just can''t understand why it was used here. Flowers are very nice, background works very well. Great colours and saturation. Exposure is spot on. Have to take off points for that border though, as it stops me focusing on the photo.', '2004-05-19 09:25:07.000000', NULL, 1),
(726362, 77111, 8522, '<td valign="top">Absolutely beautiful, but not really in the spirit of this challenge. The edge of the lake may be in the middle, but the focal point of this photo is not in the centre.</td>', 'Absolutely beautiful, but not really in the spirit of this challenge. The edge of the lake may be in the middle, but the focal point of this photo is not in the centre.', '2004-05-19 09:29:01.000000', NULL, 1),
(726363, 76081, 20521, '<td valign="top">simply lovely. perfectly measured. nice colours. elegant and no way boring.</td>', 'simply lovely. perfectly measured. nice colours. elegant and no way boring.', '2004-05-19 09:29:28.000000', NULL, 1),
(726364, 76782, 8522, '<td valign="top">Cute portrait... the shallow dof works well, and the flowers in the background really add to the shot. The photo really complements the girl... there is just the right amount of sharpness and the saturation is perfect.</td>', 'Cute portrait... the shallow dof works well, and the flowers in the background really add to the shot. The photo really complements the girl... there is just the right amount of sharpness and the saturation is perfect.', '2004-05-19 09:30:37.000000', NULL, 1),
(726366, 77032, 7743, '<td valign="top">Good expression and low key effect. 7</td>', 'Good expression and low key effect. 7', '2004-05-19 09:31:55.000000', NULL, 1),
(726368, 76209, 7743, '<td valign="top">Good choice of subject and the child''s glance leads you right to the main subject, however the contrast is a little low and the backgroung is not blurred enough and therefore distracting.  A larger aperture (smaller number) would help blur the background more. 6</td>', 'Good choice of subject and the child''s glance leads you right to the main subject, however the contrast is a little low and the backgroung is not blurred enough and therefore distracting.  A larger aperture (smaller number) would help blur the background more. 6', '2004-05-19 09:33:27.000000', NULL, 1),
(726369, 77053, 8522, '<td valign="top">Interesting idea and composition... I''d have liked the overall gamma a little higher though, with more shadow detail. Wonderful mood created by this shot.</td>', 'Interesting idea and composition... I''d have liked the overall gamma a little higher though, with more shadow detail. Wonderful mood created by this shot.', '2004-05-19 09:33:58.000000', NULL, 1),
(726372, 76168, 8522, '<td valign="top">Nice idea, but makes me feel a bit dizzy as the horizontal lines aren''t level. I''m not sure you caught this at the right time of day, as the shadow doesn''t really work for me here. Needs an extra element in the shot to push this a level higher.</td>', 'Nice idea, but makes me feel a bit dizzy as the horizontal lines aren''t level. I''m not sure you caught this at the right time of day, as the shadow doesn''t really work for me here. Needs an extra element in the shot to push this a level higher.', '2004-05-19 09:35:59.000000', NULL, 1),
(726374, 76847, 7743, '<td valign="top">Yes, it''s centered, yes it has bright colours that draw your attention, however the subject is uninteresting and the circles on the garbage can compete with the squares in the fence from a visual design standpoint.  Circles and squares can work if one is the main subject and the presence of the other is subtle.  Unfortunately, both are very prominent in your image. 4</td>', 'Yes, it''s centered, yes it has bright colours that draw your attention, however the subject is uninteresting and the circles on the garbage can compete with the squares in the fence from a visual design standpoint.  Circles and squares can work if one is the main subject and the presence of the other is subtle.  Unfortunately, both are very prominent in your image. 4', '2004-05-19 09:36:42.000000', NULL, 1),
(726375, 77059, 20521, '<td valign="top">windows xp desktop-ish ;)<br/>serious: lovely proportions, perfectly fresh colours. i can even smell the grass :)</td>', 'windows xp desktop-ish ;)serious: lovely proportions, perfectly fresh colours. i can even smell the grass :)', '2004-05-19 09:37:05.000000', NULL, 1),
(726376, 77024, 8522, '<td valign="top">Cute dog, I''m presuming that''s his home behind him, so I like the context that the background provides. It''s a little too much like a snapshot for my taste, something imaginative needs to happen here to make it more than just a personal pet photo.</td>', 'Cute dog, I''m presuming that''s his home behind him, so I like the context that the background provides. It''s a little too much like a snapshot for my taste, something imaginative needs to happen here to make it more than just a personal pet photo.', '2004-05-19 09:37:47.000000', NULL, 1),
(726377, 76293, 20521, '<td valign="top">slow and tranquil and puristic and exact. like it a lot</td>', 'slow and tranquil and puristic and exact. like it a lot', '2004-05-19 09:39:01.000000', NULL, 1),
(726378, 76741, 8522, '<td valign="top">Very entertaining pet photo. Shame about the burnt out highlights, but you had a big tonal range to capture here. Try setting your camera''s contrast settings to ''minimum'', this will enable it to capture more highlight and shadow detail. If you have the latest PS, you can also rescue shadow and highlight detail. Otherwise, use a technique known as Contrast Masking... look it up in Google. More sharpness would have been good.</td>', 'Very entertaining pet photo. Shame about the burnt out highlights, but you had a big tonal range to capture here. Try setting your camera''s contrast settings to ''minimum'', this will enable it to capture more highlight and shadow detail. If you have the latest PS, you can also rescue shadow and highlight detail. Otherwise, use a technique known as Contrast Masking... look it up in Google. More sharpness would have been good.', '2004-05-19 09:42:19.000000', NULL, 1),
(726380, 76072, 8522, '<td valign="top">Interesting picture, I think you could have adjusted the levels in PS to show much more of the highlight detail which almost looks blown out the way you''ve presented it. Adjusting the hue and saturation of the greens would have been good as well, as they look a bit dull here. Shallow dof works well here. More sharpness would have been good... is there any USM here?</td>', 'Interesting picture, I think you could have adjusted the levels in PS to show much more of the highlight detail which almost looks blown out the way you''ve presented it. Adjusting the hue and saturation of the greens would have been good as well, as they look a bit dull here. Shallow dof works well here. More sharpness would have been good... is there any USM here?', '2004-05-19 09:44:40.000000', NULL, 1),
(726383, 77109, 7743, '<td valign="top">The focus seems right on, however the chosen composition doesn''t seem to work, the image is very static.  Zooming in and filling the frame with the flower may have worked better. 4</td>', 'The focus seems right on, however the chosen composition doesn''t seem to work, the image is very static.  Zooming in and filling the frame with the flower may have worked better. 4', '2004-05-19 09:47:45.000000', NULL, 1),
(726386, 76158, 20521, '<td valign="top">like this one a lot. it looks perhaps a bit too posed, but i am not sure about that - still deciding ;) love the light.</td>', 'like this one a lot. it looks perhaps a bit too posed, but i am not sure about that - still deciding ;) love the light.', '2004-05-19 09:51:34.000000', NULL, 1),
(726393, 76850, 20521, '<td valign="top">strawberry as strawberry can :)  lovely colours, composition, light, everything.</td>', 'strawberry as strawberry can :)  lovely colours, composition, light, everything.', '2004-05-19 09:58:28.000000', NULL, 1),
(726431, 76829, 14603, '<td valign="top">Hope there`s nobody who suffers from arachnophobia on the site as they`ll have a seizure after this one pops up on the screen.<br/>Brilliantly captured</td>', 'Hope there`s nobody who suffers from arachnophobia on the site as they`ll have a seizure after this one pops up on the screen.Brilliantly captured', '2004-05-19 10:29:19.000000', NULL, 1),
