(728350, 76217, 1280, '<td valign="top">Bravo...Great job!</td>', 'Bravo...Great job!', '2004-05-20 00:14:36.000000', NULL, 1),
(728357, 76257, 1280, '<td valign="top">Wonderful detail.  Good exposure and good dof.</td>', 'Wonderful detail.  Good exposure and good dof.', '2004-05-20 00:19:25.000000', NULL, 1),
(728363, 77032, 1280, '<td valign="top">My fave so far.  The light is fantastic. 10</td>', 'My fave so far.  The light is fantastic. 10', '2004-05-20 00:21:20.000000', NULL, 1),
(728378, 77032, 11518, '<td valign="top">Fantastic capture. I''m guessing you are sitting on a black chair in front of a black background.  Very well thought out. 10</td>', 'Fantastic capture. I''m guessing you are sitting on a black chair in front of a black background.  Very well thought out. 10', '2004-05-20 00:28:34.000000', NULL, 1),
(728407, 77048, 4767, '<td valign="top">What a unique view!  Looks like a serious meditation...  (Looks like birds also meditate there).</td>', 'What a unique view!  Looks like a serious meditation...  (Looks like birds also meditate there).', '2004-05-20 00:45:28.000000', NULL, 1),
(728408, 76970, 21367, '<td valign="top">This is a very cool shot.  One does get the feeling that heavy thing could fall at any moment, so we have to keep watching the center.  The only real thing that I could see hurting your score is the distracting tree in the lower left.  I''m kind of ify with the amount of noise in the picture, there seems to be quite a bit but I have issues shooting into an overcast sky too.  I may have cloned out the tree and used the remove dust filter (I use digital image pro - don''t know what PS has for this) to clean it up a bit.  Great Idea, very good picture.</td>', 'This is a very cool shot.  One does get the feeling that heavy thing could fall at any moment, so we have to keep watching the center.  The only real thing that I could see hurting your score is the distracting tree in the lower left.  I''m kind of ify with the amount of noise in the picture, there seems to be quite a bit but I have issues shooting into an overcast sky too.  I may have cloned out the tree and used the remove dust filter (I use digital image pro - don''t know what PS has for this) to clean it up a bit.  Great Idea, very good picture.', '2004-05-20 00:46:48.000000', NULL, 1),
(728415, 75934, 21367, '<td valign="top">Very nice, you should do well with this shot.  The only thing that keeps taking me away from the center is that darn crane on top of the buildings on the right.  I might have cropped this to remove the taller building on the right, I think people would still get the centered theme even if this was tall and narrow.</td>', 'Very nice, you should do well with this shot.  The only thing that keeps taking me away from the center is that darn crane on top of the buildings on the right.  I might have cropped this to remove the taller building on the right, I think people would still get the centered theme even if this was tall and narrow.', '2004-05-20 00:52:40.000000', NULL, 1),
(728422, 76219, 21367, '<td valign="top">Excellent clarity and detail.  I think I would have gone with a square crop right about where the top of the shadow is on the stem of the flower.  That would leave enough negative space for the flower to stand out as you it does here, as it is there is just too much black for me.  A very good shot, I like it.</td>', 'Excellent clarity and detail.  I think I would have gone with a square crop right about where the top of the shadow is on the stem of the flower.  That would leave enough negative space for the flower to stand out as you it does here, as it is there is just too much black for me.  A very good shot, I like it.', '2004-05-20 00:59:41.000000', NULL, 1),
(728426, 77153, 18677, '<td valign="top">shallower DOF and less sharpening would improve this one a lot</td>', 'shallower DOF and less sharpening would improve this one a lot', '2004-05-20 01:00:52.000000', NULL, 1),
(728430, 76971, 18677, '<td valign="top">a little better focus and a little less noise would improve this one a lot</td>', 'a little better focus and a little less noise would improve this one a lot', '2004-05-20 01:03:32.000000', NULL, 1),
(728434, 76857, 21367, '<td valign="top">Excellent detail and lighting, but there is way too much going on in the background to keep my attention on the center figure.  A little less dof or I might have blurred the background to force the viewer back to the center.  I like the shot, it is a great pic that I find it very interesting.</td>', 'Excellent detail and lighting, but there is way too much going on in the background to keep my attention on the center figure.  A little less dof or I might have blurred the background to force the viewer back to the center.  I like the shot, it is a great pic that I find it very interesting.', '2004-05-20 01:05:53.000000', NULL, 1),
(728436, 77154, 18677, '<td valign="top">I like everything in this picture except for the sky.  A plain blue sky or a sky with more solid clouds would look better.</td>', 'I like everything in this picture except for the sky.  A plain blue sky or a sky with more solid clouds would look better.', '2004-05-20 01:06:42.000000', NULL, 1),
(728437, 76853, 18677, '<td valign="top">colors looked washed out.  looks like this was shot too close to midday</td>', 'colors looked washed out.  looks like this was shot too close to midday', '2004-05-20 01:07:27.000000', NULL, 1),
(728440, 77182, 18677, '<td valign="top">Great idea.  Great picture.  I love the fisheye effect here.  The sky looks unnatural, and something is wrong with the trees in the background.</td>', 'Great idea.  Great picture.  I love the fisheye effect here.  The sky looks unnatural, and something is wrong with the trees in the background.', '2004-05-20 01:08:55.000000', NULL, 1),
(728441, 77131, 18677, '<td valign="top">way too grainy.  try using Neatimage to remove some of the noise</td>', 'way too grainy.  try using Neatimage to remove some of the noise', '2004-05-20 01:09:55.000000', NULL, 1),
(728443, 77015, 18677, '<td valign="top">good idea, but poor focus and very poor lighting.</td>', 'good idea, but poor focus and very poor lighting.', '2004-05-20 01:10:52.000000', NULL, 1),
(728444, 76844, 21367, '<td valign="top">As busy as this is you still have managed to keep the viewer focus on the center of the picture.  Great Job.  Nice use of b/w.</td>', 'As busy as this is you still have managed to keep the viewer focus on the center of the picture.  Great Job.  Nice use of b/w.', '2004-05-20 01:11:17.000000', NULL, 1),
(728447, 77059, 18677, '<td valign="top">excellent photo.  i wish you had a better sky to work with (darker toward the bottom so that the cow doesn''t blend into the background).</td>', 'excellent photo.  i wish you had a better sky to work with (darker toward the bottom so that the cow doesn''t blend into the background).', '2004-05-20 01:13:02.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(728450, 76968, 18677, '<td valign="top">shallower DOF would help a lot.  just doesn''t look sharp, but it might just be a cheap camera so I won''t fault you for that.  the red thing (wind chime?) is distracting.</td>', 'shallower DOF would help a lot.  just doesn''t look sharp, but it might just be a cheap camera so I won''t fault you for that.  the red thing (wind chime?) is distracting.', '2004-05-20 01:15:28.000000', NULL, 1),
