INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(731085, 77039, 5317, '<td valign="top">I think this is a great photo,  but you probably need to have a longer shutter time.</td>', 'I think this is a great photo,  but you probably need to have a longer shutter time.', '2004-05-22 03:53:49.000000', NULL, 1),
(731086, 76577, 16301, '<td valign="top">Awesome detail and focus. The purple background is perfect, it contrasts very well with the bee''s color and makes it stand out. I don''t think you''ll get a yellow or a red ribbon, its gonna be a blue one, my top pick.<br/> <br/>Excellent work, good luck...</td>', 'Awesome detail and focus. The purple background is perfect, it contrasts very well with the bee''s color and makes it stand out. I don''t think you''ll get a yellow or a red ribbon, its gonna be a blue one, my top pick. Excellent work, good luck...', '2004-05-22 03:54:34.000000', NULL, 1),
(731112, 77121, 9906, '<td valign="top">IMHO this has been overprocessed!  Wanna see the original.<br/>TC</td>', 'IMHO this has been overprocessed!  Wanna see the original.TC', '2004-05-22 05:33:32.000000', NULL, 1),
(731115, 77115, 9906, '<td valign="top">IMHO Selective Desat needs to say something, and I don''t exactly know what your trying to say here...  Girl lost inna crowd?<br/>TC</td>', 'IMHO Selective Desat needs to say something, and I don''t exactly know what your trying to say here...  Girl lost inna crowd?TC', '2004-05-22 05:35:57.000000', NULL, 1),
(731121, 76209, 17033, '<td valign="top">I guess this was a spontaneous photo, so dificult to plan... but the background distracts from what would be a great photo. The forearm looks a bit over exposed and, given that it''s a butterfly we''re looking at, is b/w the best choice?</td>', 'I guess this was a spontaneous photo, so dificult to plan... but the background distracts from what would be a great photo. The forearm looks a bit over exposed and, given that it''s a butterfly we''re looking at, is b/w the best choice?', '2004-05-22 05:43:50.000000', NULL, 1),
(731123, 77121, 17033, '<td valign="top">the dark treee to the right pulls the attention away from the ?birch. I''m not sure the softening works with such a light subject.</td>', 'the dark treee to the right pulls the attention away from the ?birch. I''m not sure the softening works with such a light subject.', '2004-05-22 05:45:30.000000', NULL, 1),
(731127, 77153, 17033, '<td valign="top">Here the idea/mood is only provided by the title. What could be done to improve the photo? I think the buggy is too modern. Perhaps, an adult figure is needed maybe somewhere in the background (out of focus). Lighting a bit too full-on. How about b/w or sepia to give a bit of nostalgia.......just ideas.</td>', 'Here the idea/mood is only provided by the title. What could be done to improve the photo? I think the buggy is too modern. Perhaps, an adult figure is needed maybe somewhere in the background (out of focus). Lighting a bit too full-on. How about b/w or sepia to give a bit of nostalgia.......just ideas.', '2004-05-22 05:55:28.000000', NULL, 1),
(731128, 77127, 17033, '<td valign="top">Leaf in centre too blurred to be the subject of the photo</td>', 'Leaf in centre too blurred to be the subject of the photo', '2004-05-22 05:57:38.000000', NULL, 1),
(731129, 77115, 17033, '<td valign="top">The reason this doesn''t work is that we''re supposed to feel attachment to the child but she is the least colourful thing here...what about the reverse picture?....everything b/w except the girl?</td>', 'The reason this doesn''t work is that we''re supposed to feel attachment to the child but she is the least colourful thing here...what about the reverse picture?....everything b/w except the girl?', '2004-05-22 05:59:50.000000', NULL, 1),
(731130, 76853, 17033, '<td valign="top">Don''t know about this cave...are we supposed to see a profile of a head of a man with a goatee? Like it a lot. Perhaps blues need upping?</td>', 'Don''t know about this cave...are we supposed to see a profile of a head of a man with a goatee? Like it a lot. Perhaps blues need upping?', '2004-05-22 06:02:52.000000', NULL, 1),
