(731656, 76694, 7560, '<td valign="top">What a sweet face! Excellent center capture of kitty! The picture is a little hot on the left. It''s really hard to get good animal shots. If possible, this might have worked better backlit, or in black and white. 5</td>', 'What a sweet face! Excellent center capture of kitty! The picture is a little hot on the left. It''s really hard to get good animal shots. If possible, this might have worked better backlit, or in black and white. 5', '2004-05-22 20:39:28.000000', NULL, 1),
(731659, 76347, 7560, '<td valign="top">Aww! Look at that face! Nice balance, cute subject! Good use of a colored background. for this challenge, I''d clone out the bit of leg showing to make it stronger center balanced. Solid 7.</td>', 'Aww! Look at that face! Nice balance, cute subject! Good use of a colored background. for this challenge, I''d clone out the bit of leg showing to make it stronger center balanced. Solid 7.', '2004-05-22 20:41:05.000000', NULL, 1),
