(731663, 75983, 7560, '<td valign="top">Strong visual elements, nice color. Might work better for me if the image had a different angle. I  want a bit more seperation between the first two crosses. 7</td>', 'Strong visual elements, nice color. Might work better for me if the image had a different angle. I  want a bit more seperation between the first two crosses. 7', '2004-05-22 20:45:08.000000', NULL, 1),
(731664, 76400, 7560, '<td valign="top">Great shot! I lke the shallow DOF that puts the childs face as the background. Good choice as black and white with just the green showing. 7</td>', 'Great shot! I lke the shallow DOF that puts the childs face as the background. Good choice as black and white with just the green showing. 7', '2004-05-22 20:46:23.000000', NULL, 1),
(731665, 76965, 7560, '<td valign="top">Wow, simply amazing texture here. I love the detail. Black and white is a great choice. Nice sharpness. I keep supressing the urge to reach in and touch the poppy.  8</td>', 'Wow, simply amazing texture here. I love the detail. Black and white is a great choice. Nice sharpness. I keep supressing the urge to reach in and touch the poppy.  8', '2004-05-22 20:47:53.000000', NULL, 1),
(731668, 76158, 7560, '<td valign="top">Very interesting shot, and an excellent example of "grain" lending mood to an image. I might have used something to erase the footprints and tire marks on the ground to give it a cleaner feel. It also looks like you need a slight burn on the hands/lower back area where the hands fade into the back a bit. One of my favorites. 9</td>', 'Very interesting shot, and an excellent example of "grain" lending mood to an image. I might have used something to erase the footprints and tire marks on the ground to give it a cleaner feel. It also looks like you need a slight burn on the hands/lower back area where the hands fade into the back a bit. One of my favorites. 9', '2004-05-22 20:50:39.000000', NULL, 1),
(731670, 76671, 7560, '<td valign="top">Floating smartie? Cool. You might use a diffuser to cut down on the reflection on the smarties. The lighting is a tad hard for my liking. I like the use of glass (or whatever it is) to seperate one of the smarties. Nice. 5</td>', 'Floating smartie? Cool. You might use a diffuser to cut down on the reflection on the smarties. The lighting is a tad hard for my liking. I like the use of glass (or whatever it is) to seperate one of the smarties. Nice. 5', '2004-05-22 20:52:36.000000', NULL, 1),
(731700, 77137, 4494, '<td valign="top">Excellent shot!  I love the background it really comliments the fish.</td>', 'Excellent shot!  I love the background it really comliments the fish.', '2004-05-22 21:17:55.000000', NULL, 1),
(731702, 77102, 7560, '<td valign="top">I really like this image. The color makes it very dramatic, and it reminds me of sunsets back home. Great centering. The only nit is the ground isn''t totally level. But the power of the image moves it to a 9. Great job.</td>', 'I really like this image. The color makes it very dramatic, and it reminds me of sunsets back home. Great centering. The only nit is the ground isn''t totally level. But the power of the image moves it to a 9. Great job.', '2004-05-22 21:21:14.000000', NULL, 1),
