(732561, 76821, 16957, '<td valign="top">No exactly my cup of tea as far as photographs go but effective in its genre. 7</td>', 'No exactly my cup of tea as far as photographs go but effective in its genre. 7', '2004-05-23 20:56:10.000000', NULL, 1),
