(732574, 76872, 7485, '<td valign="top">The idea is great, but the harsh lighting and under-saturated colors don''t go well with the subject.</td>', 'The idea is great, but the harsh lighting and under-saturated colors don''t go well with the subject.', '2004-05-23 21:08:20.000000', NULL, 1),
(732582, 76351, 6199, '<td valign="top">just a little bit too much brightness, you loose the outline of the vase on the right side.</td>', 'just a little bit too much brightness, you loose the outline of the vase on the right side.', '2004-05-23 21:24:02.000000', NULL, 1),
(732585, 76670, 6199, '<td valign="top">colorful guy</td>', 'colorful guy', '2004-05-23 21:24:47.000000', NULL, 1),
