(732715, 76821, 7560, '<td valign="top">This reminds me of the images I made in high school doing brush on emulsions. I still have a Van Dyke brown stain on my favorite shirt. Excellent center composition and i love the way the image bleeds off the canvas. 8</td>', 'This reminds me of the images I made in high school doing brush on emulsions. I still have a Van Dyke brown stain on my favorite shirt. Excellent center composition and i love the way the image bleeds off the canvas. 8', '2004-05-23 23:27:35.000000', NULL, 1),
(732719, 77024, 14700, '<td valign="top">Its a fine photo.  I think it would have been improved if you could have eliminated the house in the background.  An all green background with a different colored subject can be striking (Especially if the background is out of focus).</td>', 'Its a fine photo.  I think it would have been improved if you could have eliminated the house in the background.  An all green background with a different colored subject can be striking (Especially if the background is out of focus).', '2004-05-23 23:32:49.000000', NULL, 1),
(732720, 76968, 14700, '<td valign="top">Beautiful child.  I think the photo would have been improved with a faster shutter speed.  It would have made for a sharper image.  Beautiful child.</td>', 'Beautiful child.  I think the photo would have been improved with a faster shutter speed.  It would have made for a sharper image.  Beautiful child.', '2004-05-23 23:34:57.000000', NULL, 1),
