(732730, 76988, 14700, '<td valign="top">Only pic in the challenge that made me smile.  Thats worth something!</td>', 'Only pic in the challenge that made me smile.  Thats worth something!', '2004-05-23 23:40:58.000000', NULL, 1),
(732731, 76773, 14700, '<td valign="top">NICE FIND!</td>', 'NICE FIND!', '2004-05-23 23:41:45.000000', NULL, 1),
(732734, 75740, 8911, '<td valign="top">This is a great shot - very imposing and impressive - but I have a little trouble with the title. The statue is indeed in the center, but it''s small enough that the title sent me searching for it, rather than enjoying the imposing effect of the architecture, or the reflections of the sky on the window behind it, both of which draw my attention much more than the statue, which is to my eyes less-impressive against the scale and solidity of the building and sky.</td>', 'This is a great shot - very imposing and impressive - but I have a little trouble with the title. The statue is indeed in the center, but it''s small enough that the title sent me searching for it, rather than enjoying the imposing effect of the architecture, or the reflections of the sky on the window behind it, both of which draw my attention much more than the statue, which is to my eyes less-impressive against the scale and solidity of the building and sky.', '2004-05-23 23:48:45.000000', NULL, 1),
(732735, 76262, 8911, '<td valign="top">Really like the warm colors of this one. It does seem as though it''s slightly tilted, which distracted me trying to figure out if it was or if that was just an optical illusion. I love the hcoice to frame it with the darkness, it really emphasizes the colors.</td>', 'Really like the warm colors of this one. It does seem as though it''s slightly tilted, which distracted me trying to figure out if it was or if that was just an optical illusion. I love the hcoice to frame it with the darkness, it really emphasizes the colors.', '2004-05-23 23:50:30.000000', NULL, 1),
(732742, 77168, 6388, '<td valign="top">i think this is my favourite of the challenge.  what a wonderful find.  most people would move this out of the way to take the photo :)  great burning around the perimeter, nice contrast, great use of grain.  well done.  P</td>', 'i think this is my favourite of the challenge.  what a wonderful find.  most people would move this out of the way to take the photo :)  great burning around the perimeter, nice contrast, great use of grain.  well done.  P', '2004-05-24 00:07:12.000000', NULL, 1),
(732753, 76259, 14012, '<td valign="top">Excellent. This is definately a ribbon winner. Only improvement would be a purer white background.</td>', 'Excellent. This is definately a ribbon winner. Only improvement would be a purer white background.', '2004-05-24 00:19:16.000000', NULL, 1),
(732755, 76158, 14012, '<td valign="top">the noise adds a nice effect</td>', 'the noise adds a nice effect', '2004-05-24 00:20:15.000000', NULL, 1),
