(734234, 76762, 16862, '<td valign="top">Glæsilega gert</td>', 'Glæsilega gert', '2004-05-24 20:15:10.000000', NULL, 0),
(734279, 77001, 19930, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by BobsterLobster:</b></div><hr/><i> Sorry you felt my comment was not worthy or useful enough to tick... even though it says exactly the same as the first comment. Maybe this is the wrong place for you, if you''re not ready to take on board constructive criticism. You already seem to think that your photos are great, why bother trying to improve? For what it''s worth, I gave you a 4. </i></td></tr></table> <br/> <br/>I''m sorry that you feel this is the wrong place for me, but since I paid I will stay, whether you like it or not. Would you be so kind as to point out to me where in any post I claim my photos are great? My claim is that this photo was better than the votes it received. For what it''s worth to you, I have had many people compliment me on my photos as well as constructively criticize them.</td>', 'Originally posted by BobsterLobster: Sorry you felt my comment was not worthy or useful enough to tick... even though it says exactly the same as the first comment. Maybe this is the wrong place for you, if you''re not ready to take on board constructive criticism. You already seem to think that your photos are great, why bother trying to improve? For what it''s worth, I gave you a 4.   I''m sorry that you feel this is the wrong place for me, but since I paid I will stay, whether you like it or not. Would you be so kind as to point out to me where in any post I claim my photos are great? My claim is that this photo was better than the votes it received. For what it''s worth to you, I have had many people compliment me on my photos as well as constructively criticize them.', '2004-05-24 20:48:15.000000', NULL, 0),
(734428, 76259, 8891, '<td valign="top">Congrats, Jean! Charming image and I''m glad the frog is OK! You never know when you might need him again!</td>', 'Congrats, Jean! Charming image and I''m glad the frog is OK! You never know when you might need him again!', '2004-05-24 22:44:28.000000', NULL, 0),
